window.QUIZ_ZK_DATA["ds02331"]=[{"id":"ds02331-pl-P4091974","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在计算机发展的初期，人们使用计算机的主要目的是处理（）问题。","opts":["A. 数据分析","B. 定量分析","C. 数值计算","D. 数学建模"],"ans":2,"explain":"在计算机发展的初期，人们使用计算机的主要目的是处理数值计算问题。"},{"id":"ds02331-pl-P4091975","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"世界上第一台计算机问世的时间是（）。","opts":["A. 1949年","B. 1948年","C. 1947年","D. 1946年"],"ans":3,"explain":"自1946年世界上第一台计算机问世以来，计算机科学和技术都得到了飞速发展。"},{"id":"ds02331-pl-P4091976","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据结构是研究（）的程序设计问题中计算机的操作对象以及它们之间的关系和操作的一门课程。","opts":["A. 非结构计算","B. 非数值计算","C. 非结果计算","D. 非分析计算"],"ans":1,"explain":"数据结构是研究非数值计算的程序设计问题中计算机的操作对象以及它们之间的关系和操作的一门课程。"},{"id":"ds02331-pl-P4091977","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"科学家沃思指出的程序基本组成是（）。","opts":["A. 代码+函数=程序","B. 算法+数据结构=程序","C. 逻辑+变量=程序","D. 指令+循环=程序"],"ans":1,"explain":"著名的瑞士计算机科学家沃思（N.Wirth）教授曾提出：算法+数据结构=程序。"},{"id":"ds02331-pl-P4091978","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据的基本单位是（）。","opts":["A. 数据对象","B. 数据结构","C. 数据元素","D. 数据项"],"ans":2,"explain":"数据元素（data element）是数据的基本单位。"},{"id":"ds02331-pl-P4091979","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"具有独立含义的最小标识单位是（）。","opts":["A. 数据对象","B. 数据结构","C. 数据元素","D. 数据项"],"ans":3,"explain":"有时一个数据元素可由若干个数据项（也称为字段、域、属性）组成，数据项是具有独立含义的最小标识单位。"},{"id":"ds02331-pl-P4091980","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"（）是带有结构的数据元素的集合。","opts":["A. 数据对象","B. 数据结构","C. 数据元素","D. 数据项"],"ans":1,"explain":"数据结构（data structure）是带有结构的数据元素的集合。"},{"id":"ds02331-pl-P4091981","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"线性结构的数据元素（结点）之间存在着（）的关系特征。","opts":["A. 一对一","B. 一对多","C. 多对多","D. 多对一"],"ans":0,"explain":"线性结构的特征是：数据元素（结点）之间存在着一对一的关系，且结构中仅有一个开始结点和一个终端结点，其余结点都是仅有一个直接前趋和一个直接后继。"},{"id":"ds02331-pl-P4091982","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"非线性结构的数据元素之间存在着（）的关系特征。","opts":["A. 一对一或一对多","B. 一对多或多对多","C. 多对多或多对一","D. 一对多或多对多"],"ans":3,"explain":"非线性结构的特征是：数据元素之间存在着一对多或多对多的关系，即一个结点可能有多个直接前趋和多个直接后继。该结构包括树形结构、图形结构和网状结构等。"},{"id":"ds02331-pl-P4091983","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"如果向量中各元素是通过指针连接存储在内存中，就称为“（）存储结构”。","opts":["A. 链式","B. 针式","C. 顺序","D. 方向"],"ans":0,"explain":"如果向量中各元素是通过指针连接存储在内存中，就称为“链式存储结构”。"},{"id":"ds02331-pl-P4091984","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"（）是具有相同性质的数据元素的集合，是数据的一个子集。","opts":["A. 数据对象","B. 数据结构","C. 数据元素","D. 数据项"],"ans":0,"explain":"数据对象（data object）是具有相同性质的数据元素的集合，是数据的一个子集。"},{"id":"ds02331-pl-P4091985","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据对象是具有（）的数据元素的集合，是数据的一个子集。","opts":["A. 相同结果","B. 相同性质","C. 相同顺序","D. 相同方向"],"ans":1,"explain":"数据对象（data object）是具有相同性质的数据元素的集合，是数据的一个子集。"},{"id":"ds02331-pl-P4091986","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"散列存储方法的基本思想是根据元素的（）直接计算出该元素的存储地址。","opts":["A. 储存方法","B. 关键字","C. 相同顺序","D. 不同方向"],"ans":1,"explain":"散列存储方法的基本思想是根据元素的关键字直接计算出该元素的存储地址。"},{"id":"ds02331-pl-P4091987","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一个值的集合和定义在这个值集上的一组操作的总称是（）。","opts":["A. 数据对象","B. 数据结构","C. 数据元素","D. 数据类型"],"ans":3,"explain":"所谓数据类型，是一个值的集合和定义在这个值集上的一组操作的总称。"},{"id":"ds02331-pl-P4091988","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"算法是对问题求解步骤的一种（）。","opts":["A. 描述","B. 指挥","C. 顺序","D. 方向"],"ans":0,"explain":"算法是对问题求解步骤的一种描述。"},{"id":"ds02331-pl-P4091989","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"严格地说，算法是由若干条（）组成的有穷序列。","opts":["A. 数据","B. 结构","C. 指令","D. 类型"],"ans":2,"explain":"严格地说，算法是由若干条指令组成的有穷序列，其中每条指令表示一个或多个操作。"},{"id":"ds02331-pl-P4091990","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一个程序如果对任何输入都不会陷入无限循环，则它就是一个（）。","opts":["A. 数据","B. 结构","C. 算法","D. 指令"],"ans":2,"explain":"一个程序如果对任何输入都不会陷入无限循环，则它就是一个算法。"},{"id":"ds02331-pl-P4091991","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"评价算法的优劣的方面中最主要的是（）。","opts":["A. 空间复杂性","B. 时间复杂性","C. 可读性","D. 可操作性"],"ans":1,"explain":"评价算法的优劣的方面中最主要的是时间复杂性，其标准即时间复杂度。"},{"id":"ds02331-pl-P4091992","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"最简单和最常用的一种数据结构是（）。","opts":["A. 顺序表","B. 列算表","C. 线性表","D. 链表"],"ans":2,"explain":"线性表（Linear_List）是最简单和最常用的一种数据结构，它是由n个数据元素（结点）a1，a2，…，an组成的有限序列。"},{"id":"ds02331-pl-P4091993","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据运算的具体实现是在（）上进行的。","opts":["A. 存储结构","B. 数据组织","C. 内存布局","D. 文件系统"],"ans":0,"explain":"数据的运算是定义在逻辑结构上的，而运算的具体实现则是在存储结构上进行的。"},{"id":"ds02331-pl-P4091994","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"线性表的顺序存储指的是将线性表的数据元素按其逻辑次序依次存入一组（）的存储单元里，用这种方法存储的线性表称为顺序表。","opts":["A. 地址连续","B. 数据组织","C. 内存布局","D. 文件系统"],"ans":0,"explain":"线性表的顺序存储指的是将线性表的数据元素按其逻辑次序依次存入一组地址连续的存储单元里，用这种方法存储的线性表称为顺序表。"},{"id":"ds02331-pl-P4091995","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"只要确定了线性表存储的（），线性表中任意一个元素都可随机存取，所以顺序表是一种随机存取结构。","opts":["A. 地址连续","B. 起始位置","C. 末端位置","D. 文件系统"],"ans":1,"explain":"只要确定了线性表存储的起始位置，线性表中任意一个元素都可随机存取，所以顺序表是一种随机存取结构。"},{"id":"ds02331-pl-P4091996","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"线性表的（）是指在线性表的第i-1个元素和第i个元素之间插入一个新元素x，使长度为n的线性表。","opts":["A. 插入运算","B. 删除运算","C. 系统运算","D. 文字运算"],"ans":0,"explain":"线性表的插入运算是指在线性表的第i-1个元素和第i个元素之间插入一个新元素x，使长度为n的线性表。"},{"id":"ds02331-pl-P4091997","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一个包含30个整数的线性表存储在数组中，如果第5个元素的存储地址是2000，第7个元素的存储地址是2040，那么第一个元素的存储地址是（）。","opts":["A. 1980","B. 1960","C. 1940","D. 1920"],"ans":3,"explain":"计算每个元素占用字节数（设为d）：根据公式，两地址差为：地址(a7​)−地址(a5​)=(7−1)d−(5−1)d=2d代入数值：2040−2000=2d⟹40=2d⟹d=20 (字节/元素)以第 5 个元素为例，代入公式：2000=base+(5−1)×202000=base+80⟹base=2000−80=1920"},{"id":"ds02331-pl-P4091998","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一个线性表有40个浮点数元素，存储在连续的数组中。如果第10个元素的存储地址是3000，每个元素占用24个字节，那么第20个元素的存储地址是（）。","opts":["A. 3250","B. 3260","C. 3240","D. 3240"],"ans":2,"explain":"第10个元素的地址是3000：Base+(10−1)×24=3000Base+(10−1)×24=3000Base+9×24=3000Base+9×24=3000Base+216=3000Base+216=3000Base=3000−216=2784Base=3000−216=2784计算第20个元素的地址现在，我们可以计算第20个元素的地址：Address of element 20=Base+(20−1)×24Address of element 20=Base+(20−1)×24=2784+19×24=2784+19×24=2784+456=2784+456=3240=3240"},{"id":"ds02331-pl-P4092000","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一个线性表采用顺序存储方式，每个元素占12个存储单元。如果第1个元素的存储地址为1000，那么第4个元素占用的最后一个存储单元的地址是（）。","opts":["A. 1100","B. 1104","C. 1047","D. 1112"],"ans":2,"explain":"第4个元素占用的最后一个存储单元的地址是第5个元素占用的第一个存储单元地址的前一个，即：1000 + （5-1） * 12 - 1 = 1047。"},{"id":"ds02331-pl-P4092001","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一个包含60个整数的线性表以顺序存储方式保存，每个整数占4个存储单元。如果第1个元素的存储地址为5000，那么第8个元素占用的最后一个存储单元的地址是（）。","opts":["A. 5104","B. 5031","C. 5028","D. 5116"],"ans":1,"explain":"在顺序存储的线性表中，每个元素按顺序连续存储，第i个元素的起始地址为：起始地址(ai)=基地址+(i−1)×每个元素占用单元数每个元素占用的最后一个存储单元地址为：起始地址(ai​)+每个元素占用单元数−1第 8 个元素的起始地址：起始地址(a8​)=5000+(8−1)×4=5000+28=5028第 8 个元素的最后一个存储单元地址：最后一个地址=5028+4−1=5031"},{"id":"ds02331-pl-P4092002","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在一个长度为n的循环链表中，随机选择一个位置插入一个新节点，平均需要移动（）个节点。","opts":["A. 0","B. n/2","C. n","D. n+1"],"ans":2,"explain":"在循环链表中，由于链表是闭合的，新节点可以插入到链表的任意位置，包括链表的头部和尾部。因此，等概率情况下，平均需要移动的节点数是n，因为每个节点都有可能成为插入点。"},{"id":"ds02331-pl-P4092003","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"顺序栈S中保存了12个数据元素，栈顶元素的存储地址是300，每个元素占5个存储单元。如果栈中每个元素进栈时，栈顶指针Stop按照Stop = S.top - 5更新，那么栈底元素的存储地址是（）。","opts":["A. 150","B. 155","C. 160","D. 165"],"ans":3,"explain":"栈底元素的存储地址 = 300 - 5 * （12 - 1） = 300 - 55 = 245。"},{"id":"ds02331-pl-P4092004","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"将12个数据元素保存在顺序表中，若第一个元素的存储地址是100，第二个元素的存储地址是105，则该顺序表最后一个元素的存储地址是（）。","opts":["A. 111","B. 144","C. 155","D. 156"],"ans":2,"explain":"线性表的第i个元素ai的存储位置LOC（ai）=LOC（ai）+（i-1）*d，所以第12个元素的地址=100+（12-1）*5=155。"},{"id":"ds02331-pl-P4092005","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"链式存储结构中存储数据元素的域称为（）。","opts":["A. 数据域","B. 指针域","C. 元素域","D. 方向域"],"ans":0,"explain":"链式存储结构，它包括两个域：存储数据元素的域称为数据域，存储直接后继存储地址的域称为指针域。"},{"id":"ds02331-pl-P4092006","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"链式存储结构中存储直接后继存储地址的域称为（）。","opts":["A. 数据域","B. 指针域","C. 元素域","D. 方向域"],"ans":1,"explain":"存储数据元素的域称为数据域，存储直接后继存储地址的域称为指针域。"},{"id":"ds02331-pl-P4092007","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"设指针变量head指向非空单循环链表的头结点，指针变量p指向终端结点，next是结点的指针域，则下列逻辑表达式中，值为真的是（）。","opts":["A. p-&gt;next-&gt;next=head","B. p-&gt;next==head","C. p-&gt;next-&gt;next==NULL","D. p-&gt;next==NULL"],"ans":1,"explain":"循环单链表的特点就是最后一个结点的指针不为空，而是指向链表的头结点。"},{"id":"ds02331-pl-P4092008","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在单链表中，每个结点的存储位置包含在其直接前趋的（）中。","opts":["A. 数据域","B. 指针域","C. 元素域","D. 方向域"],"ans":1,"explain":"在单链表中，任何两个结点的存储位置之间没有固定的联系，每个结点的存储位置包含在其直接前趋的指针域中。"},{"id":"ds02331-pl-P4092009","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"从表中任一结点开始都可以访问表中其他结点，这种结构形式的链表称为（）。","opts":["A. 单链表","B. 双向链表","C. 双循环链表","D. 单循环链表"],"ans":3,"explain":"从表中任一结点开始都可以访问表中其他结点。这种结构形式的链表称为单循环链表。"},{"id":"ds02331-pl-P4092010","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在带头结点的单链表L中，指针p指向链表的第二个数据结点，指针q指向第三个数据结点。要交换p和q所指向的两个结点中的data值，以下（）代码是不正确的。","opts":["A. int temp = p-&gt;data； p-&gt;data = q-&gt;data； q-&gt;data = temp；","B. p-&gt;next = q-&gt;next； q-&gt;next = p； int temp = p-&gt;next-&gt;data； p-&gt;next-&gt;data = q-&gt;data； q-&gt;next-&gt;data = temp；","C. int temp = p-&gt;next-&gt;data； p-&gt;next = q； q-&gt;next = p-&gt;next-&gt;next； p-&gt;next-&gt;next = q；","D. p-&gt;data = q-&gt;data； q-&gt;data = p-&gt;data；"],"ans":3,"explain":"D选项直接交换了p和q的data值，但没有考虑到p和q指向的结点在链表中的位置关系，这会导致链表断开，无法正确完成数据交换。"},{"id":"ds02331-pl-P4092011","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在一个含有n个元素的单循环链表L中，仅有尾指针指向链表的终端结点。在链表中插入一个新结点到第一个结点之前的时间复杂度是（）。","opts":["A. O（1）","B. O（n）","C. O（log n）","D. O（n log n）"],"ans":0,"explain":"由于尾指针直接指向链表的最后一个结点，可以通过尾指针直接访问到第一个结点，因此在第一个结点之前插入一个新结点的时间复杂度为O（1）。"},{"id":"ds02331-pl-P4092012","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"一般来说，结点存储密度越大，（）的利用率就越高。","opts":["A. 存储空间","B. 文件系统","C. 数字统计","D. 循环链条"],"ans":0,"explain":"一般来说，结点存储密度越大，存储空间的利用率就越高。"},{"id":"ds02331-pl-P4092013","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"顺序存储是一种（）结构，可以随机访问任一结点，访问每个结点的时间代价是一样的.","opts":["A. 自由分散","B. 随机存取","C. 直接定位","D. 快速访问"],"ans":1,"explain":"顺序存储是一种随机存取结构，可以随机访问任一结点，访问每个结点的时间代价是一样的，即每个结点的存取时间复杂度均为O（1）。"},{"id":"ds02331-pl-P4092014","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"如果经常进行的运算是插入和删除运算，以（）存储结构为宜。","opts":["A. 自由表","B. 循环表","C. 顺序表","D. 链式"],"ans":3,"explain":"如果经常进行的运算是插入和删除运算，以链式存储结构为宜。"},{"id":"ds02331-pl-P4092158","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：数据的逻辑结构可分为___和___两大类。","opts":[],"ans":null,"explain":"线性结构 非线性结构"},{"id":"ds02331-pl-P4092159","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：结构指的是____之间的相互关系，即数据的组织形式，结构中的数据元素称为结点。","opts":[],"ans":null,"explain":"数据元素"},{"id":"ds02331-pl-P4092160","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：数据的逻辑结构是从逻辑关系上描述数据的，它与数据元素的___无关，是独立于计算机的。","opts":[],"ans":null,"explain":"存储结构"},{"id":"ds02331-pl-P4092161","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：数据的存储结构是数据在___中的存储表示（映像），亦称为数据的物理结构。","opts":[],"ans":null,"explain":"计算机"},{"id":"ds02331-pl-P4092162","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：索引存储方法通常是在存储___的同时，还建立附加的索引表。","opts":[],"ans":null,"explain":"元素信息"},{"id":"ds02331-pl-P4092163","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：___是能唯一标识一个元素的一个数据项或多个数据项的组合。","opts":[],"ans":null,"explain":"关键字"},{"id":"ds02331-pl-P4092164","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：若对线性表的插入、删除运算限制在表的一端进行，则该线性表称为___。","opts":[],"ans":null,"explain":"栈"},{"id":"ds02331-pl-P4092165","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：若对线性表的插入运算限制在表的一端，而删除运算限制在表的另一端，则该线性表称为___。","opts":[],"ans":null,"explain":"队列"},{"id":"ds02331-pl-P4092166","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：结构指的是数据元素之间的相互关系，即数据的组织形式，结构中的数据元素称为___。","opts":[],"ans":null,"explain":"结点"},{"id":"ds02331-pl-P4092167","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：算法中每一条指令的执行次数都是___的，而且每一步都在___时间内完成，即算法必须在执行有限步后结束。","opts":[],"ans":null,"explain":"有限 有穷"},{"id":"ds02331-pl-P4092168","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：算法必须满足的准则有：___、输出、有穷性、___、可行性。","opts":[],"ans":null,"explain":"输入 确定性"},{"id":"ds02331-pl-P4092169","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：算法是可行的，即算法中描述的操作都可以通过有限次的___来实现。","opts":[],"ans":null,"explain":"基本运算"},{"id":"ds02331-pl-P4092170","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：一个算法的正确性，是指对于一切合法的___，该算法经过有限时间的执行都能得到正确的结果。","opts":[],"ans":null,"explain":"输入数据"},{"id":"ds02331-pl-P4092171","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：线性表是最简单和最常用的一种数据结构，它是由n个___（结点）a1，a2，…，an组成的有限序列。","opts":[],"ans":null,"explain":"数据元素"},{"id":"ds02331-pl-P4092172","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：线性表中元素之间的逻辑关系就是相邻关系，又称为___。","opts":[],"ans":null,"explain":"线性关系"},{"id":"ds02331-pl-P4092173","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：线性表中___之间的逻辑关系就是相邻关系，又称为线性关系，可见线性表是一种典型的线性结构。","opts":[],"ans":null,"explain":"元素"},{"id":"ds02331-pl-P4092174","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：线性表的顺序存储指的是将线性表的数据元素按其___次序依次存入一组地址连续的存储单元里。","opts":[],"ans":null,"explain":"逻辑"},{"id":"ds02331-pl-P4092175","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：顺序表是一种___结构。","opts":[],"ans":null,"explain":"随机存取"},{"id":"ds02331-pl-P4092176","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：假设线性表中所有元素的类型是相同的，且每个元素需占用d个存储单元，其中___的存储位置（地址）就是该元素的存储位置。","opts":[],"ans":null,"explain":"第一个单元"},{"id":"ds02331-pl-P4092177","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：由于高级程序设计语言中的数组类型具有随机存取的特性，因此，通常用___来描述顺序表。","opts":[],"ans":null,"explain":"数组"},{"id":"ds02331-pl-P4092178","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：一个包含50个实数的顺序表，每个实数占用16个存储单元。如果第一个元素的存储地址是3000，那么该顺序表最后一个元素的存储地址是___。","opts":[],"ans":null,"explain":"一个包含50个实数的顺序表，每个实数占用16个存储单元。第一个元素的存储地址是3000。由于元素是连续存储的，最后一个元素（第50个元素）的存储地址计算公式为：地址 = 首地址 + (元素个数 - 1) × 每个元素占用的单元数即：地址 = 3000 + (50 - 1) × 16 = 3000 + 49 × 16计算49 × 16 = 7843000 + 784 = 3784因此，该顺序表最后一个元素的存储地址是3784。3784\n<p style=\"text-align:start;\" size=\"1\" _root=\"[object Object]\" __ownerID=\"undefined\" __hash=\"undefined\" __altered=\"false\"><span style=\"line-height:1.2\">3784</span></p>"},{"id":"ds02331-pl-P4092179","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：一个顺序表存储了80个数据元素，第一个元素的存储地址是2000，每个元素之间相隔8个存储单元。请问该顺序表最后一个元素的存储地址是___。","opts":[],"ans":null,"explain":"4616"},{"id":"ds02331-pl-P4092180","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"解答题：给定一个有序表B=（15，22，35，47，59，70，82），表长m=7。当向其中插入元素63时，此时j等于6，因此应插入到第j个位置上，从而需要将第j个元素及之后的所有元素都向后移动一位，将第j个元素位置空出来，插入新元素63。请写出插入后的有序表。","opts":[],"ans":null,"explain":"插入后的有序表为（15，22，35，47，59，63，70，82）。"},{"id":"ds02331-pl-P4092181","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：指针P和q分别指向单链表L中的两个相邻结点，即q-&gt;next=P。若要在q所指结点后插入指针r所指结点，则执行的语句是r-&gt;next=p；____。","opts":[],"ans":null,"explain":"q-&gt;next=r"},{"id":"ds02331-pl-P4092182","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：指针p和指针q分别指向单链表L中的两个相邻结点，即q-&gt;next=p，且p所指结点不是终端结点。若要删除p所指结点，则执行的语句是___。","opts":[],"ans":null,"explain":"q-&gt;next=p-&gt;next"},{"id":"ds02331-pl-P4092183","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：动态建立单链表的常用方法有两种：一种是___，另一种则是___。","opts":[],"ans":null,"explain":"头插法 尾插法"},{"id":"ds02331-pl-P4092184","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：为了简化算法，方便操作，可在链表的开始结点之前附加一个结点，并称其为___。","opts":[],"ans":null,"explain":"头结点"},{"id":"ds02331-pl-P4092185","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：循环链表其特点是单链表中___结点的指针域不为空，而是指向链表的___，使整个链表构成一个环。","opts":[],"ans":null,"explain":"最后一个 头结点"},{"id":"ds02331-pl-P4092186","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：在单链表L中，存在一个特殊结点s，该结点的next指针域指向p。如果要判断q是否是p的直接前驱结点，正确的条件判断是____。","opts":[],"ans":null,"explain":"《数据结构》课程是以C/C++语言实现的，一般认为s、p和q是指向三个不同结点对象的指针，答案是：q-&gt;next == p；\n<p>q-&gt;next == p</p>"},{"id":"ds02331-pl-P4092187","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题：在单链表L中，给定两个指针p和q，如果要判断p和q是否指向链表中的首尾两个结点，正确的条件判断是____。","opts":[],"ans":null,"explain":"p-&gt;next==q || q-&gt;next==NULL"},{"id":"ds02331-pl-P4092122","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; int f31（int n） { if （n &lt;= 0） return 1； else if （n == 1） return 2； else return n * f31（n - 1）； } int main（） { printf（&quot;f31（0） = %d\\n&quot;， f31（0））； printf（&quot;f31（1） = %d\\n&quot;， f31（1））； printf（&quot;f31（3） = %d\\n&quot;， f31（3））； return 0； } （1）写出程序的输出结果。 （2）描述main（）调用f31（3）的递归执行过程。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：<br/><br/>f31（0） = 1<br/>f31（1） = 2<br/>f31（3） = 6<br/>（2）当main（）调用f31（3）时，递归执行过程如下：<br/><br/>f31（3） 返回 3 * f31（2）。<br/>f31（2） 返回 2 * f31（1）。<br/>f31（1） 返回 2（因为n == 1）。<br/>因此，f31（3） 最终返回 3 * （2 * 2），即 6。"},{"id":"ds02331-pl-P4092123","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; int f32（int n） { if （n &lt;= 0） return -1； else if （n == 1） return 1； else return f32（n - 1） + f32（n - 2）； } int main（） { printf（&quot;f32（0） = %d\\n&quot;， f32（0））； printf（&quot;f32（2） = %d\\n&quot;， f32（2））； printf（&quot;f32（4） = %d\\n&quot;， f32（4））； return 0； } （1）写出程序的输出结果。 （2）描述main（）调用f32（4）的递归执行过程。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：<br/><br/>f32（0） = -1<br/>f32（2） = 3<br/>f32（4） = 11<br/>（2）当main（）调用f32（4）时，递归执行过程如下：<br/><br/>f32（4） 返回 f32（3） + f32（2）。<br/>f32（3） 返回 f32（2） + f32（1）。<br/>f32（2） 返回 f32（1） + f32（0）。<br/>f32（1） 返回 1（因为n == 1）。<br/>f32（0） 返回 -1（因为n &lt;= 0）。<br/>因此，f32（4） 最终返回 （f32（2） + f32（1）） + （f32（1） + f32（0）），即 3 + 1 + 1 - 1，即 4。"},{"id":"ds02331-pl-P4092124","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; int f33（int n） { if （n &lt;= 0） return 0； else if （n == 1） return 1； else return f33（n - 1） * （n - 1）； } int main（） { printf（&quot;f33（0） = %d\\n&quot;， f33（0））； printf（&quot;f33（2） = %d\\n&quot;， f33（2））； printf（&quot;f33（4） = %d\\n&quot;， f33（4））； return 0； } （1）写出程序的输出结果。 （2）描述main（）调用f33（4）的递归执行过程。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：<br/><br/>f33（0） = 0<br/>f33（2） = 2<br/>f33（4） = 12<br/>（2）当main（）调用f33（4）时，递归执行过程如下：<br/><br/>f33（4） 返回 f33（3） * （4 - 1）。<br/>f33（3） 返回 f33（2） * （3 - 1）。<br/>f33（2） 返回 f33（1） * （2 - 1）。<br/>f33（1） 返回 1（因为n == 1）。<br/>因此，f33（4） 最终返回 （f33（2） * 2） * 3，即 2 * 3 * 2，即 12。"},{"id":"ds02331-pl-P4092125","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题：编写一个程序f32，该程序将输入的p个元素的一维数组c转换为三元组表形式存储在数组d中。 请在空白处填上适当内容将算法补充完整。 #define MAXSIZE 100 typedef int DataType； typedef struct { int i， j； // 元素行列下标 DataType value； // 元素值 } TriTupleNode； typedef struct { TriTupleNode data[MAXSIZE]； // 存储三元组数组 int p； // 一维数组的长度 } OneDimensionalArray； void f32（OneDimensionalArray *d， DataType *c， int p） { // 将一维数组c转换为三元组表形式存储在d中 int i； for （i = 0； i &lt; p； i++） { if （c[i] != 0） { // 检查元素是否为非零 （1）； // 设置行下标 （2）； // 由于是一维数组，列下标统一设为1 （3）； // 存储非零元素值 } } d-&gt;p = p； // 设置一维数组长度 } // 示例使用 int main（） { DataType c[] = {0， 3， -2， 5， 0， 7}； int p = sizeof（c） / sizeof（c[0]）； OneDimensionalArray d； f32（&amp;d， c， p）； // 打印转换后的三元组表 printf（&quot;One-dimensional array in triplet form：\\n&quot;）； for （int i = 0； i &lt; d.p； i++） { printf（&quot;（%d， 1， %d） &quot;， d.data[i].i， d.data[i].value）； } printf（&quot;\\n&quot;）； return 0； }","opts":[],"ans":null,"explain":"（1）d-&gt;data[i].i = i + 1<br/>（2）d-&gt;data[i].j = 1<br/> （3）d-&gt;data[i].value = c[i]"},{"id":"ds02331-pl-P4092126","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题：编写一个程序f33，该程序将输入的三维数组e转换为三元组表形式存储在数组f中。 请在空白处填上适当内容将算法补充完整。 #define MAXSIZE 100 typedef int DataType； typedef struct { int i， j， k； // 元素在三维数组中的行列下标 DataType value； // 元素值 } TriTupleNode； typedef struct { TriTupleNode data[MAXSIZE]； // 存储三元组数组 int m， n， o； // 三维数组的尺寸，m x n x o } ThreeDimensionalArray； void f33（ThreeDimensionalArray *f， DataType *e， int m， int n， int o） { // 将三维数组e转换为三元组表形式存储在f中 int i， j， k； （1） { for （j = 0； j &lt; n； j++） { （2） { if （e[（i * n + j） * o + k] != 0） { // 计算三维数组的索引并检查元素是否为非零 f-&gt;data[i * n * o + j * o + k].i = i + 1； // 设置行下标 f-&gt;data[i * n * o + j * o + k].j = j + 1； // 设置列下标 f-&gt;data[i * n * o + j * o + k].k = k + 1； // 设置深度下标 f-&gt;data[i * n * o + j * o + k].value = e[（i * n + j） * o + k]； // 存储非零元素值 } } } } f-&gt;m = m； // 设置三维数组的行数 f-&gt;n = n； // 设置三维数组的列数 f-&gt;o = o； // 设置三维数组的深度 }","opts":[],"ans":null,"explain":"（1）for （i = 0； i &lt; m； i++）<br/>（2） for （k = 0； k &lt; o； k++）"},{"id":"ds02331-pl-P4092127","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题：编写一个程序f42，该程序将输入的二维稀疏矩阵g转换为行索引表形式存储在数组h中。 请在空白处填上适当内容将算法补充完整。 #define MAXSIZE 100 typedef int DataType； typedef struct { int row； // 行下标 int col； // 列下标 DataType value； // 元素值 } SparseMatrixNode； typedef struct { SparseMatrixNode data[MAXSIZE]； // 存储非零元素 int size； // 非零元素的数量 } SparseMatrix； void f42（SparseMatrix *h， DataType **g， int m， int n） { // 将二维稀疏矩阵g转换为行索引表形式存储在h中 int i， j， k = 0； for （i = 0； i &lt; m； i++） { for （j = 0； j &lt; n； j++） { if （g[i][j] != 0） { // 检查元素是否为非零 （1）； // 设置行下标 （2）； // 设置列下标 h-&gt;data[k].value = g[i][j]； // 存储非零元素值 k++； // 增加非零元素计数 } } } h-&gt;size = k； // 设置非零元素的数量 }","opts":[],"ans":null,"explain":"（1）h-&gt;data[k].row = i<br/>（2） h-&gt;data[k].col = j"},{"id":"ds02331-pl-P4092629","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题： [图]https://file.mshiedu.com/exam/2024-3-22/F3anb2vahVi86Knca4q8sj2CQlh8IfyhGgBDQ3Luv4u3DZySRu.png","opts":[],"ans":null,"explain":"（1）Q-&gt;rear == Q-&gt;front<br/>（2）（Q-&gt;rear+1）% QueueSize<br/>（3）（Q-&gt;front+1）% QueueSize"},{"id":"ds02331-pl-P4092630","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法设计题：请编写一个算法，实现在循环顺序表中找出最大值和次大值的元素及其所在位置。","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/W3XZWYAWNj6aBuizMNU0bKacaFDnC5im8SnPhakOhqznD3CoBA.png\"/>"},{"id":"ds02331-pl-P4092631","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法设计题： [图]https://file.mshiedu.com/exam/2024-3-22/BXlZGeLnu7Ap4MqYlxtua03OfCGcbgVMoEnTm53M4F4gxlLP2L.png","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/KOs6dMDtjvfoKzY09kQJMLrj9IUbkwRXPClJVprhklBbHc22fa.png\"/>"},{"id":"ds02331-pl-P4092632","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法设计题：编写一个算法，将一个带头结点的单链表C分解成两个单链表C和D，其中头结点指针分别为c和d，使得C链表中含有原链表C中序号为3的倍数的元素，而D链表中含有原链表中序号为5的倍数的元素，并保持原来的相对顺序。","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/Ffwbn3zwaTG0S6ENcd2efBYXAQFe32O54P9eZ7dUwKCYdcQuX4.png\"/>"},{"id":"ds02331-pl-P4092633","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题： [图]https://file.mshiedu.com/exam/2024-3-22/1CIWNqcam95ay0kXDox2iUNSuugE6mD7pfHuAc8VArMd5tjUCw.png","opts":[],"ans":null,"explain":"1.p=p-&gt;next<br/>2.q=p-&gt;next"},{"id":"ds02331-pl-P4092634","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"算法阅读题： [图]https://file.mshiedu.com/exam/2024-3-22/WmeoScF3172mB0n8glp6aXqPr9fHaHi6C5rtQCHoU3IrKu4uZP.png","opts":[],"ans":null,"explain":"1.p=head<br/>2.p=p-&gt;next"},{"id":"ds02331-pl-P4092015","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设栈的初始状态为空，元素1，2，3，4，5，6依次入，的容量是3，能够得到的出栈序列是（）。","opts":["A. 1，2，6，4，3，5","B. 2，4，3，6，5，1","C. 3， 1，2，5，4，6","D. 3， 2，6，5，1，4"],"ans":1,"explain":"栈的特点：后进先出，且容量为3.答案B的顺序为：1进，2进，2出3进，4进，4出，3出，5进，6进，6出，5出，1出。"},{"id":"ds02331-pl-P4092016","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"栈又称为（）的线性表，简称为LIFO表。","opts":["A. 先进先出","B. 后进先出","C. 先进后出","D. 后进后出"],"ans":1,"explain":"栈又称为后进先出（Last In First Out）的线性表，简称为LIFO表。"},{"id":"ds02331-pl-P4092017","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设有初始为空的栈S，入栈序列是m，n，o，p，q，出栈序列是o，n，p，q，m，则需要为S分配的空间大小至少是（ ）。","opts":["A. 2","B. 3","C. 4","D. 5"],"ans":3,"explain":"依题意，先m，n入栈，n出栈，o，p，q入栈，o出栈，p出栈，再q出栈，n出栈，最后m出栈。故栈内最多的时候有5个元素，至少分配5个存储空间。"},{"id":"ds02331-pl-P4092018","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设栈初始为空，入栈序列为A，B，C，D，E，下列选项中，不可能得到的出栈序列是（ ）。","opts":["A. A，B，C，D，E","B. E，D，C，B，A","C. C，A，E，D，B","D. D，B，A，E，C"],"ans":2,"explain":"根据栈的后进先出规则，C不可能在A之前出栈。"},{"id":"ds02331-pl-P4092019","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设栈的初始状态为空，元素2，4，6，1，3依次入栈，不能得到的出栈序列是（ ）。","opts":["A. 6，4，2，1，3","B. 1，3，4，2，6","C. 3，1，2，4，6","D. 4，6，1，3，2"],"ans":1,"explain":"根据栈的后进先出规则，4不可能在3之前出栈。"},{"id":"ds02331-pl-P4092020","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设栈的初始状态为空，元素5，8，1，2，7，4依次入栈，不能得到的出栈序列是（ ）。","opts":["A. 4，7，2，1，8，5","B. 5，8，4，1，2，7","C. 1，5，7，2，8，4","D. 8，5，4，7，1，2"],"ans":3,"explain":"根据栈的后进先出规则，5不可能在7之前出栈。"},{"id":"ds02331-pl-P4092021","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"一个直接调用自己或间接调用自己的函数，称为（）。","opts":["A. 递归函数","B. 转换函数","C. 判断函数","D. 检验函数"],"ans":0,"explain":"一个直接调用自己或间接调用自己的函数，称为递归函数。"},{"id":"ds02331-pl-P4092022","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"队列又称为（）表。","opts":["A. 先进先出","B. 后进先出","C. 先进后出","D. 后进后出"],"ans":0,"explain":"队列的概念与现实生活中的排队相似，新来的成员总是加入队尾，排在队列最前面的总是最先离开队列，即先进先出，因此又称队列为先进先出（First In First Out，FIFO）表。"},{"id":"ds02331-pl-P4092023","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"队列是一种操作受限的线性表，体现在（）。","opts":["A. 两端插入，一端删除","B. 一端插入，两端删除","C. 一端插入，一端删除","D. 两端删除，一端插入"],"ans":2,"explain":"队列（Queue）也是一种操作受限的线性表，它只允许在表的一端进行元素插入，而在另一端进行元素删除。"},{"id":"ds02331-pl-P4092024","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"队列中元素的插入和删除分别称为（）。","opts":["A. 入队、删除","B. 出队、入队","C. 入队、出队","D. 删除、插入"],"ans":2,"explain":"在队列中，通常把元素的插入称为入队，而元素的删除称为出队。"},{"id":"ds02331-pl-P4092025","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在一个长度为N的循环队列中，队头指针和队尾指针分别为front和rear，当队列满时，下列选项中（）条件表达式为真。","opts":["A. （front + 1） % N == rear","B. （rear + 1） % N == front","C. front == rear","D. front + 1 == rear"],"ans":1,"explain":"循环队列的特点是队尾指针rear指向队列中最后一个有效元素的下一个位置。当队列满时，意味着rear指向最后一个有效元素，而rear+1位置的元素是队列中的第一个有效元素，即front指向的位置。因此，当队列满时，（rear + 1） % N 应该等于 front，这表示队列已经循环了一圈。"},{"id":"ds02331-pl-P4092026","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"循环队列E[0..P-1]中，队头指针和队尾指针分别为head和tail，队列满的条件是（）条件表达式。","opts":["A. （head + 1） % P == tail","B. （tail + 1） % P == head","C. head == tail","D. （head - 1 + P） % P == tail"],"ans":1,"explain":"在循环队列E中，当队列满时，下一个入队操作将会覆盖队头元素，即队尾指针tail的下一个位置（即（tail + 1） % P）应该指向队头指针head。因此，条件表达式（tail + 1） % P == head为真时，表示队列已满。"},{"id":"ds02331-pl-P4092027","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设有一个长度为Q的循环队列F，队头指针和队尾指针分别为start和end，当队列满时，下列选项中（）条件表达式成立。","opts":["A. （start + 1） % Q == end","B. （end + 1） % Q == start","C. start == end","D. （end - 1 + Q） % Q == start"],"ans":1,"explain":"在循环队列F中，队尾指针end指向队列中的最后一个有效元素。当队列满时，意味着end的下一个位置（即（end + 1） % Q）应该指向队头start。因此，条件表达式（end + 1） % Q == start为真时，表示队列已满。选项C（start == end）只有在队列中没有元素时才成立，因此不是队列满的条件。选项D中的（end - 1 + Q） % Q == start是错误的，因为它没有正确地表示队列满的情况。"},{"id":"ds02331-pl-P4092028","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"链队列通常使用一个附加的头结点是为了（）。","opts":["A. 增加存储空间","B. 简化边界条件","C. 提高访问速度","D. 增加队列容量"],"ans":1,"explain":"链队列一般是不带头结点的，但和单链表类似，为了简化边界条件的处理，在队头结点之前也附加一个头结点，并设队头指针指向此结点。"},{"id":"ds02331-pl-P4092029","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在计算机算法中，下列选项中（）操作通常需要使用栈来实现。","opts":["A. 计算中缀表达式的值","B. 执行二叉树的前序遍历","C. 对链表进行归并排序","D. 在散列表中处理冲突"],"ans":1,"explain":"二叉树的前序遍历是一种典型的使用栈的数据结构操作，因为前序遍历需要先访问根节点，然后遍历左子树，最后遍历右子树，这种顺序可以通过栈的后进先出特性来实现。"},{"id":"ds02331-pl-P4092030","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在处理操作系统的进程调度时，下列选项中（）调度算法可能会用到栈。","opts":["A. 轮转调度算法","B. 优先级调度算法","C. 短作业优先调度算法","D. 多级反馈队列调度算法"],"ans":0,"explain":"轮转调度算法（Round Robin Scheduling）是一种时间片轮转的调度方式，它将所有就绪进程按到达时间顺序放入一个队列，然后按照一定的时间间隔（时间片）轮流分配给每个进程。在这个过程中，当前时间片用完的进程会被放回队列末尾，这种操作类似于栈的出栈和入栈操作。"},{"id":"ds02331-pl-P4092031","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"后缀表达式计算中使用栈的目的是（）。","opts":["A. 存储操作数和结果","B. 转换字符到数值","C. 管理队列元素","D. 生成后缀表达式"],"ans":0,"explain":"在计算后缀表达式时，最后保存的值最先取出参与运算，所以要用到栈。利用前面生成的后缀表达式队列，很容易写出计算后缀表达式的算法。在算法中使用了整型栈S来存储读入的操作数和运算结果，因为在生成的后缀表达式队列中存放的是字符序列，因此在算法中要有一个数字字符到数值的转换。"},{"id":"ds02331-pl-P4092032","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"计算后缀表达式时，栈的作用是（）。","opts":["A. 转换字符和改写","B. 存储操作数和结果","C. 运算优先级控制","D. 读取队列元素"],"ans":1,"explain":"在计算后缀表达式时，最后保存的值最先取出参与运算，所以要用到栈。利用前面生成的后缀表达式队列，很容易写出计算后缀表达式的算法。在算法中使用了整型栈S来存储读入的操作数和运算结果，因为在生成的后缀表达式队列中存放的是字符序列，因此在算法中要有一个数字字符到数值的转换。"},{"id":"ds02331-pl-P4092033","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"维数（）时，称为多维数组，它可以看成是线性表的推广。","opts":["A. 小于1","B. 等于1","C. 低于1","D. 大于1"],"ans":3,"explain":"维数大于1时，称为多维数组，它可以看成是线性表的推广。"},{"id":"ds02331-pl-P4092034","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"数组的元素个数和关系在建立后的变化是（）。","opts":["A. 经常变化","B. 偶尔变化","C. 基本不变","D. 先变后不变"],"ans":2,"explain":"由于对数组一般不做插入和删除操作，因此数组一旦建立，结构中的元素个数和元素间的关系就不再发生变化。"},{"id":"ds02331-pl-P4092035","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"当数组维数为1时，数组是一种元素个数（）的线性表。","opts":["A. 动态的","B. 静态的","C. 特殊的","D. 固定的"],"ans":2,"explain":"当数组维数为1时，数组是一种元素个数固定的线性表，而维数大于1时，称为多维数组，它可以看成是线性表的推广。"},{"id":"ds02331-pl-P4092036","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"二维数组中，元素aij的直接前趋和后继说法正确的是（）。","opts":["A. 行前趋：aij-1，行后继：aij+1","B. 列前趋：ai-1j，列后继：ai+1j","C. 行前趋：ai-1y，行后继：aij-1","D. 列前趋：aij-1，列后继：ai+1j"],"ans":1,"explain":"多维数组是一种复杂的数据结构。以二维数组为例，数组元素之间的关系除了边界元素外，每个元素aij都恰好有两个直接前趋和两个直接后继：行向量上的直接前趋是aij-1和aij+1，列向量上的直接前趋是ai-1y和直接后继ai+1j。"},{"id":"ds02331-pl-P4092037","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"二维数组中，元素aij的行前趋是（）。","opts":["A. aij-1","B. ai-1j","C. ai+1j","D. aij+1"],"ans":0,"explain":"以二维数组为例，数组元素之间的关系除了边界元素外，每个元素aij都恰好有两个直接前趋和两个直接后继：行向量上的直接前趋是aij-1和aij+1，列向量上的直接前趋是ai-1y和直接后继ai+1j。"},{"id":"ds02331-pl-P4092038","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在使用高级语言编程时，一般都是使用（）来存储矩阵。","opts":["A. 一维链表","B. 二维数组","C. 三维矩阵","D. 哈希表"],"ans":1,"explain":"由于矩阵具有元素数目固定以及元素按下标关系有序排列等特点，所以在使用高级语言编程时，一般都是使用二维数组来存储矩阵。"},{"id":"ds02331-pl-P4092039","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"相同值的元素或者零元素在矩阵中的分布有一定规律的矩阵是（）。","opts":["A. 特殊矩阵","B. 稀疏矩阵","C. 三维矩阵","D. 哈希矩阵"],"ans":0,"explain":"所谓特殊矩阵，指的是相同值的元素或者零元素在矩阵中的分布有一定规律的矩阵。"},{"id":"ds02331-pl-P4092040","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"对称矩阵中的元素是关于（）对称的。","opts":["A. 副对角线","B. 主对角线","C. 矩阵中心","D. 行列交换"],"ans":1,"explain":"对称矩阵中的元素是关于主对角线对称的，所以只需要存储矩阵上三角或下三角的元素即可，让两个对称的元素共享一个存储空间。"},{"id":"ds02331-pl-P4092041","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"一般情况下，三角矩阵的常数c均为（）。","opts":["A. 正数","B. 任意","C. 零","D. 整数"],"ans":2,"explain":"一般情况下，三角矩阵的常数c均为零。"},{"id":"ds02331-pl-P4092042","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"稀疏矩阵非零元素的三元组按行优先顺序排列形成的线性表称为（）。","opts":["A. 行列表","B. 列列表","C. 三元组表","D. 对角线表"],"ans":2,"explain":"如果将表示稀疏矩阵非零元素的三元组按行优先的顺序排列，则可得到一个其结点均为三元组的线性表，将这种线性表的顺序存储结构称为三元组表。"},{"id":"ds02331-pl-P4092043","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"当矩阵中非零元素数量远小于总元素数时，这种矩阵称为（）。","opts":["A. 稠密矩阵","B. 稀疏矩阵","C. 单位矩阵","D. 对角矩阵"],"ans":1,"explain":"有一种矩阵，其中有s个非零元素，而s远远小于矩阵元素的总数，通常把这种矩阵称为稀疏矩阵。"},{"id":"ds02331-pl-P4092044","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"对于一个5行5列的对称矩阵B，采用行优先压缩存储方式保存其上三角部分，每个元素占3个单元。若矩阵B中第一个元素b11的存储地址是20，元素b35的存储地址是（）。","opts":["A. 45","B. 54","C. 60","D. 63"],"ans":0,"explain":"元素b35存储在k=[5*（5+1）/2]+4=15，即sb[15]中，则b35的地址为LOC（b11）+（k-1）*m=20+（15-1）*3=45，其中m为每个元素占用的单元数。"},{"id":"ds02331-pl-P4092188","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：栈是限定在表的一端进行插入和删除运算的线性表，通常将插入、删除的一端称为___，另一端称为___。不含元素的空表称为___。","opts":[],"ans":null,"explain":"栈顶 栈底 空栈"},{"id":"ds02331-pl-P4092189","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：一个直接或间接调用自己的函数称为____。","opts":[],"ans":null,"explain":"递归函数"},{"id":"ds02331-pl-P4092190","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：递归算法设计中的最小子问题称为递归的___。","opts":[],"ans":null,"explain":"终止条件（或递归出口）"},{"id":"ds02331-pl-P4092191","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：递归算法的设计一般分为两步：第一步称为___，第二步中的最小子问题称为递归的___。","opts":[],"ans":null,"explain":"递归步骤 终止条件"},{"id":"ds02331-pl-P4092192","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：程序设计语言中的函数调用和返回是利用___来实现的。","opts":[],"ans":null,"explain":"栈"},{"id":"ds02331-pl-P4092193","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：队列的顺序存储结构称为___。","opts":[],"ans":null,"explain":"顺序队列"},{"id":"ds02331-pl-P4092194","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：为了充分利用数组空间，克服上溢，可将数组空间想象为一个环状空间，并称这种环状数组表示的队列为___。","opts":[],"ans":null,"explain":"循环队列"},{"id":"ds02331-pl-P4092195","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：给定一个顺序队列的定义如下： #define MaxQueueSize 100 typedef struct { int data[MaxQueueSize]； int front； int rear； } SeqQueue； 规定队列的前端位置在数组下标为0的一端，后端位置在数组下标为 rear 的位置。 请回答下列问题： （1）用语句表示判断队列非空的条件。 （2）用语句表示连续 k（k 为正整数）次出队的操作。","opts":[],"ans":null,"explain":"（1）判断队列非空的条件是队列的前端 front 和后端 rear 索引不相等。在C语言中，这个条件可以用以下语句表示：<br/><br/>if （front != rear） {<br/>    // 队列非空<br/>}<br/>如果 front 和 rear 相等，这意味着队列为空，因为队列中没有任何元素。<br/><br/>（2）连续 k 次出队操作意味着我们需要从队列中移除 k 个元素。在C语言中，我们可以通过循环结构来实现这个操作，如下所示：<br/><br/>int k； // 假设k已经是一个正整数<br/>for （int i = 0； i &lt; k； i++） {<br/>    if （front != rear） { // 确保队列中有元素<br/>        printf（&quot;出队元素： %d\\n&quot;， data[front]）； // 假设data数组存储整数<br/>        front++； // 移动front指针<br/>    }<br/>}<br/>这个循环会检查队列是否非空，然后从队列的前端移除元素，通过增加 front 索引来实现。注意，如果队列在循环中变为空，循环将会停止，不会尝试从空队列中出队。"},{"id":"ds02331-pl-P4092196","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：已知字符集 {f， g， h， i， j} 中字符 f 出现的频次为 4，字符 g 出现的频次为 5，字符 h 出现的频次为 2，字符 i 出现的频次为 3，字符 j 出现的频次为 6。使用哈夫曼编码为这些字符生成编码，并假设字符 g 的编码是 00，字符 j 的编码是 10。请计算其余三个字符的编码分别是什么？","opts":[],"ans":null,"explain":"字符 f 的编码是 001。<br/>字符 h 的编码是 000。<br/>字符 i 的编码是 110。"},{"id":"ds02331-pl-P4092197","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：已知字符集 {x， y， z， t， u} 中字符 x 出现的频次为 1，字符 y 出现的频次为 3，字符 z 出现的频次为 5，字符 t 出现的频次为 2，字符 u 出现的频次为 4。使用哈夫曼编码为这些字符生成编码，并假设字符 z 的编码是 0，字符 y 的编码是 10。请计算其余三个字符的编码分别是什么？","opts":[],"ans":null,"explain":"字符 x 的编码是 11。<br/>字符 t 的编码是 11（与 x 相同，因为在合并时它们被视为一个节点）。<br/>字符 u 的编码是 1。"},{"id":"ds02331-pl-P4092198","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：已知字符集 {A， B， C， D， E} 中字符 A 出现的频次为 6，字符 B 出现的频次为 2，字符 C 出现的频次为 4，字符 D 出现的频次为 5，字符 E 出现的频次为 1。使用哈夫曼编码为这些字符生成编码，并假设字符 D 的编码是 0，字符 E 的编码是 11。请计算其余三个字符的编码分别是什么？","opts":[],"ans":null,"explain":"字符 A 的编码是 1。<br/>字符 B 的编码是 10（与 E 相同，因为在合并时它们被视为一个节点）。<br/>字符 C 的编码是 01。"},{"id":"ds02331-pl-P4092199","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：已知字符集 {M， N， O， P， Q} 中字符 M 出现的频次为 8，字符 N 出现的频次为 1，字符 O 出现的频次为 6，字符 P 出现的频次为 3，字符 Q 出现的频次为 2。使用哈夫曼编码为这些字符生成编码，并假设字符 M 的编码是 0，字符 N 的编码是 10。请计算其余三个字符的编码分别是什么？","opts":[],"ans":null,"explain":"字符 O 的编码是 1。<br/>字符 P 的编码是 111（与 N，Q 合并后的节点相同，因为在合并时它们被视为一个节点）。<br/>字符 Q 的编码是 110。"},{"id":"ds02331-pl-P4092200","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：队列的链式存储结构称为___。它是一种限制在表头删除和表尾插入操作的___。","opts":[],"ans":null,"explain":"链队列 单链表"},{"id":"ds02331-pl-P4092201","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：已知循环队列存储在一维数组B[0..m-1]中，头指针是head，尾指针是tail，初始时head的值和tail的值均是1，则第2个入队元素存储在数组中的存储位置的下标是_______。","opts":[],"ans":null,"explain":"2"},{"id":"ds02331-pl-P4092202","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：在一个循环队列C[0..k-1]中，头指针初始化为2，尾指针初始化为0，若每个元素入队后队列的尾指针增加1，头指针增加2，当第3个元素入队后，该元素存储在数组中的存储位置的下标是_______。","opts":[],"ans":null,"explain":"4"},{"id":"ds02331-pl-P4092203","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：设有循环队列D[0..l-1]，头指针和尾指针初始值分别为3和0，当队列满时，头指针和尾指针的值相等。若队列的容量为5，当第4个元素入队后，该元素存储在数组中的存储位置的下标是_______。","opts":[],"ans":null,"explain":"1"},{"id":"ds02331-pl-P4092204","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：在后缀表达式中，不仅不需要___，而且还能完全免除___规则。","opts":[],"ans":null,"explain":"括号 算符优先"},{"id":"ds02331-pl-P4092205","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：给定一个顺序栈的类型定义如下： #define MaxSize 100 typedef struct { int data[MaxSize]； int top； } SeqStack； 请回答下列问题： （1）用语句表示判断栈非空的条件。 （2）用语句表示连续m（m为正整数）次入栈的操作。","opts":[],"ans":null,"explain":"（1）判断栈非空的条件是 top != 0。<br/>（2）连续m次入栈的操作可以通过循环实现，如下所示：<br/><br/>for （int i = 0； i &lt; m； i++） {<br/>    // 假设有一个数组 items，存储要入栈的元素<br/>    if （top &lt; MaxSize - 1） {<br/>        data[top + 1] = items[i]；<br/>        top++；<br/>    } else {<br/>        printf（&quot;栈满，无法继续入栈。\\n&quot;）；<br/>    }<br/>}"},{"id":"ds02331-pl-P4092206","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：给定一个顺序队列的类型定义如下： #define MaxQueueSize 100 typedef struct { int data[MaxQueueSize]； int front； int rear； } SeqQueue； 请回答下列问题： （1）用语句表示判断队列非空的条件。 （2）用语句表示连续n（n为正整数）次出队的操作。","opts":[],"ans":null,"explain":"（1）判断队列非空的条件是 front &lt;= rear。<br/>（2）连续n次出队的操作可以通过循环实现，如下所示：<br/><br/>for （int i = 0； i &lt; n； i++） {<br/>    if （front &lt;= rear） {<br/>        printf（&quot;出队元素： %d\\n&quot;， data[front]）；<br/>        front++；<br/>    } else {<br/>        printf（&quot;队列为空，无法出队。\\n&quot;）；<br/>    }<br/>}"},{"id":"ds02331-pl-P4092207","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：给定一个链栈的类型定义如下： typedef struct StackNode { int data； struct StackNode *next； } StackNode， *LinkStack； 请回答下列问题： （1）用语句表示判断链栈非空的条件。 （2）用语句表示连续p（p为正整数）次出栈的操作。","opts":[],"ans":null,"explain":"（1）判断链栈非空的条件是 LinkStack != NULL。<br/>（2）连续p次出栈的操作可以通过循环实现，如下所示：<br/><br/>for （int i = 0； i &lt; p； i++） {<br/>    if （LinkStack != NULL） {<br/>        StackNode *temp = LinkStack；<br/>        printf（&quot;出栈元素： %d\\n&quot;， temp-&gt;data）；<br/>        LinkStack = LinkStack-&gt;next；<br/>        free（temp）；<br/>    } else {<br/>        printf（&quot;栈为空，无法继续出栈。\\n&quot;）；<br/>    }<br/>}<br/>在这些题目中，我们提供了顺序栈、顺序队列和链栈的类型定义，并要求编写代码来判断数据结构是否非空以及执行连续的入栈/出栈操作。这些操作是栈和队列基本操作的一部分，对于理解这些数据结构的工作原理至关重要。"},{"id":"ds02331-pl-P4092208","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：一般都是采用___存储的方法来表示数组。","opts":[],"ans":null,"explain":"顺序"},{"id":"ds02331-pl-P4092209","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：在二维数组A[10][8]中，每个数组元素占用4个存储单元，则数组A需要的存储单元个数是___。","opts":[],"ans":null,"explain":"320"},{"id":"ds02331-pl-P4092210","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：特殊矩阵，指的是___的元素或者___在矩阵中的分布有一定规律的矩阵。","opts":[],"ans":null,"explain":"相同值 零元素"},{"id":"ds02331-pl-P4092211","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：当用三元组来表示非零元素时，对稀疏矩阵进行压缩存储通常有两种方法：___和___。","opts":[],"ans":null,"explain":"顺序存储 链式存储"},{"id":"ds02331-pl-P4092212","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：链式存储一般采用的是___法。","opts":[],"ans":null,"explain":"十字链表"},{"id":"ds02331-pl-P4092213","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：给定以下数据序列（45， 23， 67， 90， 15， 38， 56， 72， 04， 29， 61， 83），使用二路归并排序算法将其排成升序序列。请给出各趟排序结果。","opts":[],"ans":null,"explain":"第1趟排序结果：<br/><br/>左侧序列：（45， 23， 67， 90）<br/>右侧序列：（15， 38， 56， 72， 04， 29， 61， 83）<br/>第2趟排序结果：<br/><br/>左侧序列细分并排序后：（23， 45， 67， 90）<br/>右侧序列细分并排序后：（04， 15， 29， 38， 56， 61， 72， 83）<br/>第3趟排序结果：<br/><br/>合并后的序列：（04， 15， 23， 29， 38， 45， 56， 61， 67， 72， 83， 90）"},{"id":"ds02331-pl-P4092214","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：给定以下数据序列（34， 76， 21， 69， 38， 46， 83， 11， 52， 90， 27），使用二路归并排序算法将其排成升序序列。给出各趟排序结果。","opts":[],"ans":null,"explain":"第1趟排序结果：<br/><br/>左侧序列：（34， 21， 38， 27）<br/>右侧序列：（76， 69， 46， 83， 11， 52， 90）<br/>第2趟排序结果：<br/><br/>左侧序列细分并排序后：（21， 27， 34， 38）<br/>右侧序列细分并排序后：（11， 46， 52， 69， 76， 83）<br/>第3趟排序结果：<br/><br/>合并后的序列：（11， 21， 27， 34， 38， 46， 52， 69， 76， 83， 90）"},{"id":"ds02331-pl-P4092643","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：[图]https://file.mshiedu.com/exam/2024-3-22/4nYWPMfnqIBGuuldaQQByb62bJdN1qFffB8vOi6tZW2Pjr3fqm.png","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/GQTRtGRkYMytrfViJVEbBfL9OxFiOyG99HcfsZbXQP0tSL6guV.png\"/>"},{"id":"ds02331-pl-P4092128","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法阅读题：给定以下递归函数： int f（int arr[]， int left， int right， int target） { int mid； if （left &lt;= right） { mid = （left + right） / 2； if （arr[mid] == target） { return mid； } else if （target &lt; arr[mid]） { return f（arr， left， mid - 1， target）； } else { return f（arr， mid + 1， right， target）； } } return -1； // 如果没有找到目标值 } 这个函数用于在一个有序数组中查找特定元素的位置。如果找到，返回元素的索引；如果未找到，返回-1。 现在，假设我们有以下数组 int b[8] = {2， 4， 6， 8， 10， 12， 14， 16}；，请回答以下问题： （1）执行 printf（&quot;f=%d\\n&quot;， f（b， 0， 7， 10））； 后，输出的内容是什么？ （2）f 函数的功能是什么？","opts":[],"ans":null,"explain":"（1）执行 printf（&quot;f=%d\\n&quot;， f（b， 0， 7， 10））； 后，输出的内容是 4。<br/>（2）f 函数的功能是在有序数组 arr 中查找目标值 target 的位置。它接受四个参数：数组 arr、左边界 left、右边界 right 和要查找的目标值 target。如果找到目标值，返回其在数组中的索引；如果在整个查找范围内未找到目标值，则返回 -1 表示目标值不在数组中。"},{"id":"ds02331-pl-P4092129","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法阅读题：给定以下递归函数，它用于计算阶乘： int factorial（int n） { if （n == 0） { return 1； } else { return n * factorial（n - 1）； } } （1）执行 printf（&quot;%d\\n&quot;， factorial（5））； 后，输出的内容是什么？ （2）factorial 函数的功能是什么？","opts":[],"ans":null,"explain":"（1）执行 printf（&quot;%d\\n&quot;， factorial（5））； 后，输出的内容是 120。<br/>（2）factorial 函数的功能是计算一个非负整数n的阶乘。如果n为0，则阶乘值为1。否则，它递归地计算 n * factorial（n - 1），直到n减小到0。"},{"id":"ds02331-pl-P4092130","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法阅读题：给定以下递归函数，它用于计算斐波那契数列中的第n项： int fibonacci（int n） { if （n &lt;= 1） { return n； } else { return fibonacci（n - 1） + fibonacci（n - 2）； } } （1）执行 printf（&quot;%d\\n&quot;， fibonacci（7））； 后，输出的内容是什么？ （2）fibonacci 函数的功能是什么？","opts":[],"ans":null,"explain":"（1）执行 printf（&quot;%d\\n&quot;， fibonacci（7））； 后，输出的内容是 13。<br/>（2）fibonacci 函数的功能是计算斐波那契数列中的第n项。如果n小于或等于1，直接返回n。否则，递归地计算前两项的和。"},{"id":"ds02331-pl-P4092131","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法阅读题：给定以下递归函数，它用于反转字符串： void reverseString（char *str） { if （*str） { reverseString（str + 1）； printf（&quot;%c&quot;， *str）； } } （1）给定字符串 char s[] = &quot;Hello&quot;；，执行 reverseString（s）； 后，输出的内容是什么？ （2）reverseString 函数的功能是什么？","opts":[],"ans":null,"explain":"（1）执行 reverseString（s）； 后，输出的内容是 olleH。<br/>（2）reverseString 函数的功能是反转并打印给定字符串。它递归地处理字符串的每个字符，直到到达字符串的开头。每次递归调用后，它会打印当前指向的字符，从而实现反转输出的效果。"},{"id":"ds02331-pl-P4092132","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法设计题：已知函数 g（n） 的定义如下： 若 n 为负数，则 g（n） = -g（-n）。 若 n 等于0，则 g（0） = 1。 若 n 等于1，则 g（1） = 2。 若 n 为大于1的整数，则 g（n） = g（n-1） + g（n-2）。 请编写一个递归算法，实现计算 g（n） 的功能，并给出计算 g（5） 的结果。","opts":[],"ans":null,"explain":"我们可以按照函数 g（n） 的定义来编写递归算法。首先，我们需要处理基本情况：负数、0和1。然后，对于大于1的整数，我们递归地调用 g（n-1） 和 g（n-2） 并将结果相加。递归算法：<br/>function g（n）：<br/>    if n &lt; 0：<br/>        return -g（-n）<br/>    elif n == 0：<br/>        return 1<br/>    elif n == 1：<br/>        return 2<br/>    else：<br/>        return g（n-1） + g（n-2）<br/>现在我们使用这个递归算法来计算 g（5）：<br/>g（5） = g（4） + g（3）<br/>g（4） = g（3） + g（2）<br/>g（3） = g（2） + g（1）<br/>g（2） = g（1） + g（0）<br/>将已知的基本情况代入：<br/>g（1） = 2<br/>g（0） = 1<br/>继续代入计算：<br/>g（3） = 2 + 1 = 3<br/>g（2） = 2 + 1 = 3<br/>g（4） = 3 + 3 = 6<br/>g（5） = 6 + 3 = 9<br/>因此，`g（5）` 的结果是 9。<br/>这个递归算法将会在每次调用时检查 n 是否为负数、0或1，如果不是，则递归地计算 g（n-1） 和 g（n-2） 并将它们相加，直到达到基本情况。这种方法可以有效地计算出 g（n） 的值。"},{"id":"ds02331-pl-P4092133","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法设计题：如果矩阵 B 中存在这样的一个元素 B[[i]， j]，满足：B[i][j] 是第 i 行元素中次大的值，且又是第 j 列元素中次小的值，则称此元素为该矩阵的一个次关键点。假设以二维数组存储矩阵 B[m][n]，试编写求出矩阵中所有次关键点的算法。","opts":[],"ans":null,"explain":"void FindSubKeyPoints（int B[m][n]， int m， int n） {<br/>    int *rowMax = （int *）malloc（m * sizeof（int））；<br/>    int *colMin = （int *）malloc（n * sizeof（int））；<br/>    int i， j， k；                               // 初始化行最大值和列最小值数组<br/>    for （i = 0； i &lt; m； i++） {<br/>        rowMax[i] = B[i][0]；<br/>    }<br/>    for （j = 0； j &lt; n； j++） {<br/>        colMin[j] = B[0][j]；                    // 计算每一行的最大值<br/>    }     for （i = 0； i &lt; m； i++） {<br/>        for （j = 1； j &lt; n； j++） {<br/>            if （B[i][j] &gt; rowMax[i]） {<br/>                rowMax[i] = B[i][j]；           // 计算每一列的最小值<br/><br/>            }<br/>        }<br/>    }<br/>       for （j = 0； j &lt; n； j++） {<br/>        for （i = 1； i &lt; m； i++） {<br/>            if （B[i][j] &lt; colMin[j]） {<br/>                colMin[j] = B[i][j]；           // 找出次关键点<br/><br/>            }<br/>        }<br/>    }<br/>       for （i = 0； i &lt; m； i++） {<br/>        for （j = 0； j &lt; n； j++） {<br/>            if （B[i][j] == rowMax[i] - 1 &amp;&amp; B[i][j] == colMin[j] + 1） {<br/>                printf（&quot;（%d， %d）\\n&quot;， i， j）；  // 显示次关键点<br/>            }<br/>        }<br/>    }<br/><br/>       free（rowMax）；<br/>       free（colMin）；                               // 释放内存<br/><br/>}"},{"id":"ds02331-pl-P4092635","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法设计题： [图]https://file.mshiedu.com/exam/2024-3-22/V5zaXmn08TQqmOZ9qNhOzxB9c3GwRnGjvLMfOs46SsNRISD5yl.png","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/rnvY1hSlUs2KYELjNVnXB8TpJa1smjKY6tQ8bVxvhTN5ip9c2l.png\"/>"},{"id":"ds02331-pl-P4092636","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法阅读题：[图]https://file.mshiedu.com/exam/2024-3-22/wWlB31XPBY2B2jm0lGWZMzonTDTArBSXdXUZI9Lx77NIqubawy.png","opts":[],"ans":null,"explain":"（1）*a<br/>（2）k++<br/>（3）k"},{"id":"ds02331-pl-P4092045","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"已知广义表LS=（（（a，b）），（（c，，（f））），（d）），（e，（g，h）），LS的深度是（）。","opts":["A. 2","B. 3","C. 4","D. 5"],"ans":2,"explain":"一个表展开后所含括号的层数称为广义表的深度。即表中每个元素 的括号匹配数加1。"},{"id":"ds02331-pl-P4092046","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"由于广义表中的元素本身又可以具有结构，是一种带有层次的非线性结构，因此通常采用（）结构。","opts":["A. 顺序存储","B. 链式存储","C. 散列存储","D. 树形存储"],"ans":1,"explain":"由于广义表中的元素本身又可以具有结构，是一种带有层次的非线性结构，因此难以用顺序存储结构表示，通常采用链式存储结构，每个元素可用一个结点表示。"},{"id":"ds02331-pl-P4092047","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"已知广义表LQ=（（a），（（b，c），d）），LQ的深度是（ ）。","opts":["A. 1","B. 2","C. 3","D. 4"],"ans":2,"explain":"广义表LQ=（（a），（（b，c），d））包含两层括号，因此其深度为2。"},{"id":"ds02331-pl-P4092048","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"广义表LP=（（p，（q，r）），（s，（t，（u，v）））的深度是（ ）。","opts":["A. 2","B. 3","C. 4","D. 5"],"ans":2,"explain":"广义表LP=（（p，（q，r）），（s，（t，（u，v）））包含三层括号，其中最内层括号还有嵌套，因此其深度为4。"},{"id":"ds02331-pl-P4092049","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"已知广义表LQ=（x，（y，（z，（w））），（v，u）），LQ的表尾是（ ）。","opts":["A. （y，（z，（w））），（v，u）","B. （（y，（z，（w））），（v，u））","C. （x，（y，（z，（w）））），（v，u）","D. （x，（y，（z，（w）））），（v，u）"],"ans":1,"explain":"根据广义表的定义，LQ的表头是x，其余部分（y，（z，（w））），（v，u）构成LQ的表尾。因此，表尾是（（y，（z，（w））），（v，u））。"},{"id":"ds02331-pl-P4092050","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"非空树中有且仅有一个特定的结点称为（）。","opts":["A. 子节点","B. 边节点","C. 根节点","D. 叶子节点"],"ans":2,"explain":"对于任意一棵非空树：有且仅有一个特定的称为根（Root）的结点。"},{"id":"ds02331-pl-P4092051","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"树中结点的层次是（）算起。","opts":["A. 从叶节点开始","B. 从根开始","C. 与父节点相同","D. 与子节点相同"],"ans":2,"explain":"树中结点的层次是从根开始算起，根为第一层，其余结点的层次等于其双亲结点的层数加1。"},{"id":"ds02331-pl-P4092052","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"二叉树的每个结点至多只有（）棵子树。","opts":["A. 一","B. 两","C. 三","D. 四"],"ans":1,"explain":"二叉树（BinaryTree）是n（n≥0）个结点的有限集合，它的每个结点至多只有两棵子树。"},{"id":"ds02331-pl-P4092053","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在一般情况下，存储二叉树的存储方式是（）。","opts":["A. 链式存储","B. 指针存储","C. 动态存储","D. 顺序存储"],"ans":0,"explain":"在一般情况下，多采用链式存储方式来存储二叉树。"},{"id":"ds02331-pl-P4092054","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"已知一棵完全二叉树共有15个结点，其中分支结点有5个，那么叶子结点的个数是（ ）。","opts":["A. 5","B. 7","C. 8","D. 10"],"ans":2,"explain":"在完全二叉树中，如果分支结点有5个，那么这棵树的深度至少为2（因为每个分支结点至少有两个子结点）。由于是完全二叉树，第3层将会填满，即有4个叶子结点。剩余的结点（15-4-5=6）将会在第4层形成叶子结点，但由于是完全二叉树，第4层的叶子结点数必须是偶数，所以叶子结点的个数为6+1=7。因此，叶子结点的总数为4+7=11，但选项中没有11，所以需要检查解析是否有误。实际上，由于完全二叉树的特性，第4层的叶子结点数应该是2的幂次方，所以正确的叶子结点数为2^2=4，加上第3层的4个叶子结点，总共有8个叶子结点。"},{"id":"ds02331-pl-P4092055","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在一棵深度为h的满二叉树中，共有2^h-1个结点，那么当结点总数为15时，该树的深度是（）。","opts":["A. 2","B. 3","C. 4","D. 5"],"ans":2,"explain":"根据满二叉树的性质，结点总数为2^h-1，其中h为树的深度。给定结点总数为15，我们可以通过对数来解这个方程。以2为底的对数方程为：log2（15+1） = log2（16） = 4。因此，该满二叉树的深度为4。"},{"id":"ds02331-pl-P4092056","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"遍历算法中的递归终止条件是（）。","opts":["A. 二叉树递归","B. 二叉树归零","C. 二叉树基准","D. 二叉树为空"],"ans":3,"explain":"遍历算法中的递归终止条件是二叉树为空。"},{"id":"ds02331-pl-P4092057","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在一棵非空二叉树的中序遍历序列中，所有列在根结点后面的是（ ）。","opts":["A. 左子树中的全部结点","B. 右子树中的部分结点","C. 右子树中的全部结点","D. 左右子树中的部分结点"],"ans":2,"explain":"中序遍历二叉树的递归定义 若二叉树非空，则依次进行操作：A.中序遍历左子树；B.访问根结点；C.中序遍历右子树。"},{"id":"ds02331-pl-P4092058","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"我们把对一棵二叉线索链表结构中所有结点的空指针域按照某种遍历次序加线索的过程称为（）。","opts":["A. 递归化","B. 归零化","C. 线索化","D. 基准化"],"ans":3,"explain":"我们把对一棵二叉线索链表结构中所有结点的空指针域按照某种遍历次序加线索的过程称为线索化。"},{"id":"ds02331-pl-P4092059","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在一个包含n个节点的单链表中，空指针域的数量是（）。","opts":["A. n","B. n+1","C. n-1","D. 1"],"ans":1,"explain":"在单链表中，除了第一个节点外，每个节点都有一个指向下一个节点的指针。因此，n个节点的单链表将有n-1个内部指针和1个空指针（链表的尾部节点的下一个指针）。所以，总的空指针域的数量是n+1。"},{"id":"ds02331-pl-P4092060","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"孩子兄弟表示法即以（）作为树的存储结构。","opts":["A. 二叉链表","B. 循环链表","C. 单链表","D. 哈希链表"],"ans":0,"explain":"孩子兄弟表示法又称二叉链表表示法，即以二叉链表作为树的存储结构。"},{"id":"ds02331-pl-P4092061","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"树的后序遍历的顺序是（）。","opts":["A. 根-左-右","B. 左-右-根","C. 右-左-根","D. 右-根-左"],"ans":1,"explain":"后序遍历森林则是从左到右依次按后序（后根）次序遍历森林中的每一棵树。"},{"id":"ds02331-pl-P4092062","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"一棵树的后序遍历等价于其对应二叉树的（）遍历。","opts":["A. 前序遍历","B. 中序遍历","C. 后序遍历","D. 层序遍历"],"ans":1,"explain":"前序遍历一棵树等价于前序遍历该树对应的二叉树，而后序遍历一棵树则等价于中序遍历该树对应的二叉树。"},{"id":"ds02331-pl-P4092063","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"森林的前序遍历的顺序是（）。","opts":["A. 根-左-右","B. 左-右-根","C. 右-左-根","D. 右-根-左"],"ans":0,"explain":"前序遍历森林是从左到右依次按前序（先根）次序遍历森林中的每一棵树。"},{"id":"ds02331-pl-P4092064","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"哈夫曼树定义中，WPL代表（）。","opts":["A. 权重总数","B. 权重平均值","C. 带权路径长度","D. 叶子节点数"],"ans":2,"explain":"在权值为w1，w2，…，wn的n个叶结点构成的所有二叉树中，带权路径长度WPL最小的二叉树称为哈夫曼树或最优二叉树。"},{"id":"ds02331-pl-P4092065","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"构建哈夫曼树的过程中，（）选择新树的左右子树。","opts":["A. 随机选取两棵树","B. 选择权值最大的两棵树","C. 选择根结点权值最小的两棵树","D. 选择根结点数量最少的两棵树"],"ans":2,"explain":"在森林F中选出两棵根结点的权值最小的树作为一棵新树的左、右子树，且置新树的附加根结点的权值为其左、右子树上根结点的权值之和。"},{"id":"ds02331-pl-P4092066","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"利用哈夫曼树求得的用于通信的二进制编码称为（）。","opts":["A. ASCII编码","B. 哈夫曼编码","C. 绝对编码","D. 相对编码"],"ans":1,"explain":"利用哈夫曼树求得的用于通信的二进制编码称为哈夫曼编码。"},{"id":"ds02331-pl-P4092067","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"电报通信是由传递（）的二进制码组成的字符串。","opts":["A. 数字","B. 文字","C. 图像","D. 符号"],"ans":1,"explain":"电报通信是由传递文字的二进制码组成的字符串。"},{"id":"ds02331-pl-P4092215","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：当广义表LS非空时，称第一个元素a₁是LS的___，其余元素组成的表（a2，…，an）称为LS的___。","opts":[],"ans":null,"explain":"表头 表尾"},{"id":"ds02331-pl-P4092216","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：广义表具有___和___的性质。","opts":[],"ans":null,"explain":"递归 共享"},{"id":"ds02331-pl-P4092217","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：广义表是一种多层次的线性结构，实际上就是一种___结构。","opts":[],"ans":null,"explain":"树形"},{"id":"ds02331-pl-P4092218","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：广义表（（a，b），（c，d），e，（f（g，h）））的表尾是（）。","opts":[],"ans":null,"explain":"（（c，d），e，（f，（g，h）））"},{"id":"ds02331-pl-P4092219","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"解答题：已知有下列广义表，试求出下面广义表的表头head、表尾tail、表长length和深度depth。 （1） E = （1， （2， （3， 4））， 5， （6， 7））； （2） F = （I， （J， （）））； （3） G = （M， （N， （P， Q）， R）， S）； （4） H = （T， （（U）， V）， （W， X， （Y， （Z））））；","opts":[],"ans":null,"explain":"（1） head（E） = 1，tail（E） = （（2， （3， 4））， 5， （6， 7）），<br/>length（E） = 4，depth（E） = 3；<br/><br/>（2） head（F） = I，tail（F） = （（J， （）），），<br/>length（F） = 2，depth（F） = 3；<br/><br/>（3） head（G） = M，tail（G） = （（N， （P， Q）， R）， S），<br/>length（G） = 4，depth（G） = 4；<br/><br/>（4） head（H） = T，tail（H） = （（（U）， V）， （W， X， （Y， （Z）））），<br/>length（H） = 5，depth（H） = 4."},{"id":"ds02331-pl-P4092220","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：广义表中的元素本身可以具有结构，是一种带有层次的___结构。","opts":[],"ans":null,"explain":"非线性"},{"id":"ds02331-pl-P4092221","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：广义表H=（5，（H，1））的深度是______。","opts":[],"ans":null,"explain":"∞"},{"id":"ds02331-pl-P4092222","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题：广义表N=（14，（N，4））的深度是______。","opts":[],"ans":null,"explain":"∞"},{"id":"ds02331-pl-P4092223","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：树形结构是一类重要的非线性数据结构，树中结点之间具有明确的层次关系，并且结点之间有分支，非常类似于真正的树，是一个___结构。","opts":[],"ans":null,"explain":"递归"},{"id":"ds02331-pl-P4092224","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：在树形图表示中，结点通常用___表示，结点名一般写在圆圈内或写在圆圈旁。","opts":[],"ans":null,"explain":"圆圈"},{"id":"ds02331-pl-P4092225","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：度数为零的结点称为___或___。","opts":[],"ans":null,"explain":"叶子结点 终端结点"},{"id":"ds02331-pl-P4092226","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：度数不为零的结点称为___或___。","opts":[],"ans":null,"explain":"非终端结点 分支结点"},{"id":"ds02331-pl-P4092227","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：除根结点之外，分支结点也称为___，而根结点又称为___。","opts":[],"ans":null,"explain":"内部结点 开始结点"},{"id":"ds02331-pl-P4092228","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：树的一个结点拥有的子树数称为该结点的___。","opts":[],"ans":null,"explain":"度"},{"id":"ds02331-pl-P4092229","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：在二叉树的第i层上，至多有___个结点（i≥1）。","opts":[],"ans":null,"explain":"2i-1"},{"id":"ds02331-pl-P4092230","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：深度为k的二叉树，至多有___个结点（k≥1）。","opts":[],"ans":null,"explain":"2k-1"},{"id":"ds02331-pl-P4092231","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：具有n个结点的完全二叉树的深度为____或___。","opts":[],"ans":null,"explain":"⎿logn⏌+1  （⎿log（n+1）⏌）"},{"id":"ds02331-pl-P4092232","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：在二叉树的链式存储表示中，通常采用的方法是：每个结点设置三个域，即___、____和____。","opts":[],"ans":null,"explain":"值域 左指针域 右指针域"},{"id":"ds02331-pl-P4092233","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：在遍历方案DLR中，因为访问根结点的操作在遍历左、右子树之前，故称之为___或___。","opts":[],"ans":null,"explain":"前序遍历 先根遍历"},{"id":"ds02331-pl-P4092234","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：给定一个完全二叉树，其节点按层遍历的顺序存储在一维数组B[0..m-1]中，其中m是节点的总数。则数组中B[j]（1≤j≤m-1）的父结点在数组中的位置是____。","opts":[],"ans":null,"explain":"B[（j-1）/2]"},{"id":"ds02331-pl-P4092235","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：在树结构中，每个结点的双亲是___的。","opts":[],"ans":null,"explain":"唯一"},{"id":"ds02331-pl-P4092236","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：由于树根没有兄弟，所以转换后的二叉树，其根结点的右子树必___。","opts":[],"ans":null,"explain":"为空"},{"id":"ds02331-pl-P4092644","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题： [图]https://file.mshiedu.com/exam/2024-3-22/uL8SGaJVS6cYKpqrQCRJSvuzkiDrsDiTzbW2cQH2Lkrxfyjerf.png","opts":[],"ans":null,"explain":"①C，②H，③D，④E，⑤H，⑥D，⑦B，⑧E，⑨G，⑩A"},{"id":"ds02331-pl-P4092645","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题：设电文字符集是{e1，e2，e3，e4，e5}，它们出现的次数分别为：{50，10，16，8，12}。现要为该字符集设计哈夫曼编码。请回答下列问题。 （1）画出得到的哈夫曼树。 （2）给出各符号的哈夫曼编码。","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/4DhlHOM7nJGmXFFXkhLlyJsZxcP6jKcuWC5SzYrHUC4S5CJvV4.png\"/>"},{"id":"ds02331-pl-P4092646","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题：[图]https://file.mshiedu.com/exam/2024-3-22/ydWSEc2WDYf0FHFHjdCIVKdL7S5S2JPSDYh976lYfvcjSymMJs.png","opts":[],"ans":null,"explain":"（1） 哈夫曼树中每个叶子节点的编码是根据从根节点到该叶子节点的路径确定的，左子路径用0表示，右子路径用1表示。根据下列图，我们可以推断出以下编码（假设根节点下方的左子树代表编码中的0，右子树代表1）：<br/>叶子节点a的编码是0<br/>叶子节点b的编码是10<br/>叶子节点c的编码是110<br/>叶子节点d的编码是111<br/>（2） 根据上述分析，哈夫曼编码表如下：<br/>a： 0<br/>b： 10<br/>c： 110<br/>d： 111"},{"id":"ds02331-pl-P4092134","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：阅读以下函数 f32，并回答问题。 f32（int b[]， int m） { int i， j； for （i = 0； i &lt; m； i++） { for （j = 0； j &lt; m - i - 1； j++） { if （b[j] &gt; b[j + 1]） { int temp = b[j]； b[j] = b[j + 1]； b[j + 1] = temp； } } } } 给定数组 inta = （10， 7， 5， 12， 3， 8， 1， 6），则执行语句 f32（a， 8）； 后，数组 inta 的内容是什么？ （1）执行 f32（a， 8）； 后，数组 inta 的内容是什么？ （2）说明方框内 for 循环的作用。","opts":[],"ans":null,"explain":"（1）执行 f32（a， 8）； 后，数组 inta 的内容是：（1， 3， 5， 6， 7， 8， 10， 12）。<br/><br/>（2）方框内的 for 循环是一个嵌套循环，用于实现冒泡排序算法。外层循环控制排序的轮数，内层循环负责在每一轮中通过比较相邻的元素并交换位置来对数组进行排序。在每一轮排序中，内层循环都会将当前未排序部分的最大元素“冒泡”到未排序部分的末尾。这个过程会重复进行，直到整个数组变得有序。在这个例子中，数组 inta 经过8轮比较和交换后，最终变成了一个升序数组。"},{"id":"ds02331-pl-P4092135","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：编写一个C语言函数，该函数接受一个整数数组和一个整数n作为参数，然后使用选择排序算法对数组进行升序排序。 void selectionSort（int arr[]， int n） { int i， j， minIndex， temp； for （i = 0； i &lt; n - 1； i++） { // 寻找[i， n）区间中的最小元素的索引 minIndex = i； for （j = i + 1； j &lt; n； j++） { if （arr[j] &lt; arr[minIndex]） { minIndex = j； } } // 将找到的最小元素与arr[i]交换位置 if （minIndex != i） { temp = arr[i]； arr[i] = arr[minIndex]； arr[minIndex] = temp； } } } 给定数组 inta = （64， 25， 12， 22， 11），则执行语句 selectionSort（a， 5）； 后，数组 inta 的内容是什么？","opts":[],"ans":null,"explain":"执行 selectionSort（a， 5）； 后，数组 inta 的内容是：（11， 12， 22， 25， 64）。"},{"id":"ds02331-pl-P4092136","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：编写一个C语言函数，该函数接受一个字符串数组和一个整数n作为参数，然后使用冒泡排序算法对字符串数组按照字典序进行升序排序。 void bubbleSortStrings（char arr[][20]， int n） { int i， j； char temp[20]； for （i = 0； i &lt; n - 1； i++） { for （j = 0； j &lt; n - i - 1； j++） { if （strcmp（arr[j]， arr[j + 1]） &gt; 0） { // 字符串比较结果大于1时，交换两个字符串的位置 strcpy（temp， arr[j]）； strcpy（arr[j]， arr[j + 1]）； strcpy（arr[j + 1]， temp）； } } } } 给定字符串数组 strArray = {&quot;apple&quot;， &quot;banana&quot;， &quot;cherry&quot;， &quot;date&quot;}，则执行语句 bubbleSortStrings（strArray， 4）； 后，字符串数组 strArray 的内容是什么？","opts":[],"ans":null,"explain":"执行 bubbleSortStrings（strArray， 4）； 后，字符串数组 strArray 的内容是：{&quot;apple&quot;， &quot;banana&quot;， &quot;cherry&quot;， &quot;date&quot;}。"},{"id":"ds02331-pl-P4092137","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：给定以下待排序记录的数据类型定义和排序函数框架，完成直接选择排序算法的C语言实现。 #define MAXSIZE 100 typedef struct { int key； } RecType； typedef RecType SeqList[MAXSIZE]； // 函数声明：对序列R进行直接选择排序，排序为升序 void selectionSort（SeqList R， int n） { int i， j， k； int minIndex； // 用于记录当前找到的最小元素的索引 for （i = 0； i &lt; n - 1； i++） { // 初始化minIndex为当前第一个元素的索引 minIndex = i； // 从i+1开始，找到从i到n-1中最小元素的索引 for （j = i + 1； j &lt; n； j++） { if （R[j].key &lt; R[minIndex].key） { minIndex = j； // 更新minIndex为当前找到的最小元素的索引 } } // 将找到的最小元素与第i个元素交换 if （minIndex != i） { RecType temp = R[i]； R[i] = R[minIndex]； R[minIndex] = temp； } } } 现在有一个待排序的序列 SeqList R = { {45}， {23}， {67}， {89}， {12}， {34}， {56}， {78}， {90} }；，执行 selectionSort（R， 9）； 后，序列R的排序结果是什么？","opts":[],"ans":null,"explain":"执行 selectionSort（R， 9）； 后，序列R的排序结果是：{ {12}， {23}， {34}， {45}， {56}， {67}， {78}， {89}， {90} }。"},{"id":"ds02331-pl-P4092138","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：给定以下待排序记录的数据类型定义，编写一个C语言函数实现顺序表的直接插入排序。 #define MAXSIZE 100 typedef int KeyType； typedef struct { KeyType key； } RecType； typedef RecType SeqList[MAXSIZE]； // 函数声明：对顺序表R进行直接插入排序 void directInsertionSort（SeqList R， int n） { int i， j； RecType temp； for （i = 1； i &lt; n； i++） { temp = R[i]； j = i； // 将R[i]与它前面的元素比较，如果R[i]的key小于R[j-1]的key，则交换它们的位置 while （j &gt; 0 &amp;&amp; temp.key &lt; R[j - 1].key） { R[j] = R[j - 1]； j--； } // 将temp插入到正确的位置 R[j] = temp； } } 现在有一个待排序的顺序表 SeqList R = { {5}， {2}， {9}， {1}， {3}， {7}， {8}， {4}， {6} }；，执行 directInsertionSort（R， 9）； 后，顺序表R的排序结果是什么？","opts":[],"ans":null,"explain":"执行 directInsertionSort（R， 9）； 后，顺序表R的排序结果是：{ {1}， {2}， {3}， {4}， {5}， {6}， {7}， {8}， {9} }。"},{"id":"ds02331-pl-P4092637","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"算法阅读题： [图]https://file.mshiedu.com/exam/2024-3-22/1a0oeL069vaP5R4WDnIBSJwE6GW5vNbIjpDviLR4n6jQzo938Y.png","opts":[],"ans":null,"explain":"输出结果：7，3，9，6，1，5，2，8，4。"},{"id":"ds02331-pl-P4092638","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：[图]https://file.mshiedu.com/exam/2024-3-22/VIZPMbhHocOPB3cJH5FtRn0Bi7Xadux2TjeoCdeUUsHdnPIiWO.png","opts":[],"ans":null,"explain":"（1）ACDEB；（2）O（n）。"},{"id":"ds02331-pl-P4092068","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"无向图中所有顶点的度数之和是8，则顶点的最大度数是（ ）。","opts":["A. 5","B. 6","C. 7","D. 4"],"ans":3,"explain":"结点度数之和为边数的两倍，设边数为x，则2*x=8，解得x=4。"},{"id":"ds02331-pl-P4092069","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"无向图中所有顶点的度数之和是12，则顶点的最大度数是（ ）。","opts":["A. 5","B. 6","C. 7","D. 4"],"ans":1,"explain":"结点度数之和为边数的两倍，设边数为x，则2*x=12，解得x=6。"},{"id":"ds02331-pl-P4092070","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"用邻接矩阵表示有n个顶点和e条边的无向图，采用压缩方式存储，矩阵中零元素的个数是（）。","opts":["A. n（n+1）/2-e","B. n（n+1）/2-2e","C. nxn-e","D. nxn-2e"],"ans":0,"explain":"有n个顶点的无向图的邻接矩阵一共有n*n个元素，由于是对称矩阵，采用压缩存储，共存储n（n+1）/2个元素，其中只有e个元素是非零元素，其他都是零元素，共n（n+1）/2-e个。"},{"id":"ds02331-pl-P4092071","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"无向图G中所有顶点的度数之和是20，则G中的边数是（）。","opts":["A. 10","B. 20","C. 30","D. 40"],"ans":0,"explain":"一条边是2度，20除以2等于10条边。"},{"id":"ds02331-pl-P4092072","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"邻接矩阵是表示图形中（）之间相邻关系的矩阵。","opts":["A. 底点","B. 顶点","C. 端点","D. 间隔"],"ans":1,"explain":"邻接矩阵是表示图形中顶点之间相邻关系的矩阵。"},{"id":"ds02331-pl-P4092073","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"对于有向图，可以有（）个邻接矩阵。","opts":["A. 4","B. 3","C. 2","D. 1"],"ans":2,"explain":"对于有向图，可以有两个邻接矩阵，一个表示出边，一个表示入边。"},{"id":"ds02331-pl-P4092074","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"设有向图G含有n个顶点、e条边，使用邻接表存储。对G进行广度优先遍历的算法的时间复杂度是（）。","opts":["A. 0（n）","B. 0（e）","C. 0 （n+e）","D. 0（nxe）"],"ans":2,"explain":"邻接表存储的有向图进行广度优先遍历的时间复杂度与图中的顶点个数以及边数都相关。"},{"id":"ds02331-pl-P4092075","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"有向图G有n个顶点和e条边，G保存在邻接矩阵M中，M中0与1的个数差是（）。","opts":["A. n（n+1）/2-e","B. n（n+1）/2-2e","C. nxn-e","D. nxn-2e"],"ans":3,"explain":"邻接矩阵一共有n*n个元素，因为边的个数是e，所以邻接矩阵中1的个数为e，则0的个数就是n*n-e。所以0与1的个数差是nxn-2e。"},{"id":"ds02331-pl-P4092076","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"有向图G中所有顶点的度数之和是24，则G中弧的数量是（）。","opts":["A. 10","B. 12","C. 14","D. 16"],"ans":1,"explain":"在有向图中，所有顶点的度数之和是所有边数的2倍，因为一条边的两个端点具有两个“度”。"},{"id":"ds02331-pl-P4092077","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"若图G的邻接表中有奇数个表结点，则G是（）。","opts":["A. 含奇数个顶点的图","B. 无向图","C. 含偶数个顶点的图","D. 有向图"],"ans":3,"explain":"无向图的邻接表的表结点的个数一定是偶数，为边数的2倍。若图G的邻接表中有奇数个表结点，则图G一定是有向图。"},{"id":"ds02331-pl-P4092078","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"若用邻接矩阵存储有向图，矩阵中主对角线以下的元素均为零，则关于该图拓扑排序序列的结论是（）。","opts":["A. 存在，且唯一","B. 存在，且不唯一","C. 存在，可能不唯一","D. 无法确定是否存在"],"ans":2,"explain":"一个有向图有拓扑序列的充要条件是该图是有向无环图。对角线以下元素均为零，表明只有顶点i顶点i。"},{"id":"ds02331-pl-P4092079","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"设有向图G含有n个顶点、e条边，使用邻接表存储。对G进行深度优先搜索遍历算法的时间复杂度是（）。","opts":["A. 0（n）","B. 0（e）","C. 0（n+e）","D. 0（nxe）"],"ans":2,"explain":"当用邻接矩阵表示图时，需要对n个顶点进行访问，所以共需要搜索n2个矩阵元素，而在邻接表上则需要将边表中所有0（e）个结点搜一遍，因此深度优先搜索遍历算法的时间复杂度为0（n+e）。"},{"id":"ds02331-pl-P4092080","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"深度优先搜索（Depth First Search，DFS）遍历类似于树的（）遍历。","opts":["A. 顺序","B. 后序","C. 前序","D. 中序"],"ans":2,"explain":"深度优先搜索（Depth First Search，DFS）遍历类似于树的前序（先根）遍历。"},{"id":"ds02331-pl-P4092081","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"一棵具有n个顶点的生成树有仅有（）条边。","opts":["A. n-2","B. n-1","C. n+2","D. n+1"],"ans":1,"explain":"一棵具有n个顶点的生成树有仅有n-1条边，但有n-1条边的图不一定是生成树。"},{"id":"ds02331-pl-P4092082","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"生成树各边的权值总和称为（）。","opts":["A. 该树的权","B. 最大生成树","C. 最小生成树","D. 该树的枝"],"ans":0,"explain":"我们把生成树各边的权值总和称为该树的权，把权值最小的生成树称为图的最小生成树（MST）。"},{"id":"ds02331-pl-P4092083","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在有向网中，（）顶点被称为源点。","opts":["A. 最后一个顶点","B. 第一个顶点","C. 中间顶点","D. 随机顶点"],"ans":1,"explain":"带权有向图（又称有向网），并称路径上的第一个顶点为源点，最后一个顶点为终点。"},{"id":"ds02331-pl-P4092084","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"AOV网是（）的简称。","opts":["A. 有向有环图","B. 无向无环图","C. 有向无环图","D. 环状活动图"],"ans":2,"explain":"通常，我们把这种顶点表示活动、边表示活动间先后关系的有向无环图（DAG）称为顶点活动网，简称AOV网。"},{"id":"ds02331-pl-P4092237","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：两个无向连通图均含有15个顶点，它们之间的边数差最大是_______。","opts":[],"ans":null,"explain":"45"},{"id":"ds02331-pl-P4092238","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：两个无向连通图均含有8个顶点，它们之间的边数差最大是_______。","opts":[],"ans":null,"explain":"28"},{"id":"ds02331-pl-P4092239","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：在含有m个顶点、f条边的无向连通图中，f的取值范围是_______。","opts":[],"ans":null,"explain":"m-1≤f≤m（m-1）/2"},{"id":"ds02331-pl-P4092240","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：将无向图邻接表称为___，将有向图的邻接表称为___，将邻接表的表头向量称为___。","opts":[],"ans":null,"explain":"边表 出边表 顶点表"},{"id":"ds02331-pl-P4092241","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：若无向图中有n个顶点和e条边，则它的邻接表共有___个头结点和___个表结点。","opts":[],"ans":null,"explain":"n 2e"},{"id":"ds02331-pl-P4092242","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：图G的邻接矩阵是一个非对称矩阵，则图G一定是____图。","opts":[],"ans":null,"explain":"有向"},{"id":"ds02331-pl-P4092243","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：一个连通图的____是包含图中所有顶点的极小连通子图。","opts":[],"ans":null,"explain":"生成树"},{"id":"ds02331-pl-P4092244","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：无向图G中含7个顶点，顶点间的边是随机设置的，为保证图G在任何情况下都是连通的，则需要的边数最少是___。","opts":[],"ans":null,"explain":"16"},{"id":"ds02331-pl-P4092245","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：求单源最短路径的迪杰斯特拉（Dijkstra）算法是按照路径___不减的次序求出各条路径的。","opts":[],"ans":null,"explain":"长度"},{"id":"ds02331-pl-P4092246","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：如果图G存在拓扑排序序列，则G必为___。","opts":[],"ans":null,"explain":"有向无环图"},{"id":"ds02331-pl-P4092247","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：如果有向无环图G中仅有一个顶点的入度为0，若要求G的拓扑序列不唯的顶点。一，则G中必须存在一个出度至少为____。","opts":[],"ans":null,"explain":"2"},{"id":"ds02331-pl-P4092248","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题：由AOV网构造拓扑序列的过程称为___。","opts":[],"ans":null,"explain":"拓扑排序"},{"id":"ds02331-pl-P4092647","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题： [图]https://file.mshiedu.com/exam/2024-3-22/37ZjWnOno9xwZTHn3uWCOgOZNRynDMtfRUXQbp0fGMJYFVSRZv.png","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/8iBygZj0MNvWU7sjpkyrV8D5sBvBViz6d431IbwsdLkJachx3x.png\"/>"},{"id":"ds02331-pl-P4092648","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题：[图]https://file.mshiedu.com/exam/2024-3-22/yIkp5updvPlu8x030gNSx8tcQuZkCW0gz34OuLHK35D6hqAumu.png","opts":[],"ans":null,"explain":"（1）是有向无环图。<br/>（2）该图的拓扑排序序列有：（1，2，5，4，7，3，6）和（1，2，5，4，3，7，6）"},{"id":"ds02331-pl-P4092649","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题：[图]https://file.mshiedu.com/exam/2024-3-22/QyjRSDwMef7RvweSokMT5m9KKXhuHtTINFFyOoKySkYCF0Oexi.png","opts":[],"ans":null,"explain":"（1）ABCEGDF ACEGBDF ADFGBCE<br/>（2）ABCDEFG ADCBFEG"},{"id":"ds02331-pl-P4092650","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"解答题：[图]https://file.mshiedu.com/exam/2024-3-22/ayz8LXDhW0Xq6S0HEAVgzupurPm6o7rXGM1YcjvzIjoNcBO9A6.png","opts":[],"ans":null,"explain":"1.（E，F）<br/>2.（C，D）<br/>3.（A，B）<br/>4.（B，C）<br/>5.（D，A）"},{"id":"ds02331-pl-P4092139","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; void fun（int a[]， int dk， int n） { int i， j， temp； for （i = dk； i &lt; n； i++） { if （a[i] &lt; a[i - dk]） { temp = a[i]； j = i - dk； while （j &gt;= 0 &amp;&amp; temp &lt; a[j]） { a[i + dk] = a[j]； i += dk； j -= dk； } a[j + dk] = temp； } } } void f34（int a[]， int d[]， int t， int n） { fun（a， d[0]， n）； for （int i = 1； i &lt; t； i++） { int new_dk = d[i] - d[i - 1]； fun（a， new_dk， n）； } } int main（） { int a[] = {5， 3， 1， 7， 4， 2}； int d[] = {2， 1}； int t = sizeof（d） / sizeof（int）； int n = sizeof（a） / sizeof（int）； f34（a， d， t， n）； for （int i = 0； i &lt; n； i++） { printf（&quot;%d &quot;， a[i]）； } printf（&quot;\\n&quot;）； return 0； } （1）写出程序的输出结果。 （2）描述函数f34（）的功能。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：1 2 3 4 5 7<br/>（2）函数f34（）的功能是对数组a进行基于间隔d的插入排序。数组d中的每个元素代表一个间隔，函数fun（）会对每个间隔进行一次插入排序操作。在main（）中，a数组被排序，首先基于间隔2进行排序，然后基于间隔1（这实际上是对整个数组进行排序）。"},{"id":"ds02331-pl-P4092140","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; void fun（int a[]， int dk， int n） { int i， j， temp； for （i = dk； i &lt; n； i++） { if （a[i] &gt; a[i - dk]） { temp = a[i]； j = i - dk； while （j &gt;= 0 &amp;&amp; temp &gt; a[j]） { a[i - dk] = a[j]； j -= dk； } a[j + dk] = temp； } } } void f35（int a[]， int d[]， int t， int n） { for （int i = 0； i &lt; t； i++） { fun（a， d[i]， n）； } } int main（） { int a[] = {4， 6， 2， 8， 5， 3}； int d[] = {2， 1}； int t = sizeof（d） / sizeof（int）； int n = sizeof（a） / sizeof（int）； f35（a， d， t， n）； for （int i = 0； i &lt; n； i++） { printf（&quot;%d &quot;， a[i]）； } printf（&quot;\\n&quot;）； return 0； } （1）写出程序的输出结果。 （2）描述函数f35（）的功能。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：2 3 4 5 6 8<br/>（2）函数f35（）的功能是对数组a进行基于间隔d的降序插入排序。数组d中的每个元素代表一个间隔，函数fun（）会对每个间隔进行一次降序插入排序操作。在main（）中，a数组被排序，首先基于间隔2进行降序排序，然后基于间隔1（这实际上是对整个数组进行降序排序）。"},{"id":"ds02331-pl-P4092141","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; void fun（int a[]， int dk， int n） { int i， j， temp； for （i = dk； i &lt; n； i++） { if （a[i] &lt; a[i - dk]） { temp = a[i]； j = i - dk； do { a[j + dk] = a[j]； j -= dk； } while （j &gt;= 0 &amp;&amp; temp &lt; a[j]）； a[j + dk] = temp； } } } void f36（int a[]， int d[]， int t， int n） { for （int i = 0； i &lt; t； i++） { int new_dk = d[i]； fun（a， new_dk， n）； } } int main（） { int a[] = {7， 9， 3， 6， 4， 2}； int d[] = {3， 2， 1}； int t = sizeof（d） / sizeof（int）； int n = sizeof（a） / sizeof（int）； f36（a， d， t， n）； for （int i = 0； i &lt; n； i++） { printf（&quot;%d &quot;， a[i]）； } printf（&quot;\\n&quot;）； return 0； } （1）写出程序的输出结果。 （2）描述函数f36（）的功能。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：2 3 4 6 9 7<br/>（2）函数f36（）的功能是对数组a进行基于间隔d的冒泡排序。数组d中的每个元素代表一个间隔，函数fun（）会对每个间隔进行一次冒泡排序操作。在main（）中，a数组被排序，首先基于间隔3进行排序，然后基于间隔2，最后基于间隔1（这实际上是对整个数组进行排序）。"},{"id":"ds02331-pl-P4092142","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"算法阅读题：阅读下列程序，回答问题。 #include &lt;stdio.h&gt; // 函数用于计算并输出数组中所有元素的平均值 void average（int arr[]， int size） { int sum = 0； for （int i = 0； i &lt; size； ++i） { sum += arr[i]； } printf（&quot;The average is： %f\\n&quot;， （double）sum / size）； } // 函数用于计算并输出数组中所有正数元素的平均值 void positiveAverage（int arr[]， int size） { int sum = 0； int positiveCount = 0； for （int i = 0； i &lt; size； ++i） { if （arr[i] &gt; 0） { sum += arr[i]； positiveCount++； } } if （positiveCount &gt; 0） { printf（&quot;The average of positive numbers is： %f\\n&quot;， （double）sum / positiveCount）； } else { printf（&quot;No positive numbers to average.\\n&quot;）； } } int main（） { int arr[] = {-1， 3， 5， -7， 4， 2}； int size = sizeof（arr） / sizeof（arr[0]）； average（arr， size）； printf（&quot;\\n&quot;）； positiveAverage（arr， size）； return 0； } （1）写出程序的输出结果。 （2）描述函数positiveAverage（）的功能。","opts":[],"ans":null,"explain":"（1）程序的输出结果为：<br/>The average is： 1.000000<br/>The average of positive numbers is： 4.000000<br/>（2）函数positiveAverage（）的功能是计算并输出数组中所有正数元素的平均值。它首先初始化sum和positiveCount变量，然后遍历数组arr，只有当元素大于0时，才将其值累加到sum中，并增加positiveCount。遍历完成后，如果至少有一个正数元素，函数将计算正数元素的平均值并输出；如果没有正数元素，则输出提示信息“没有正数元素来计算平均值”。<br/><br/>这个程序首先调用average函数计算并输出包含正数和负数元素的平均值，然后调用positiveAverage函数来计算并输出仅包含正数元素的平均值。"},{"id":"ds02331-pl-P4092085","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下列选项中不属于内部排序方法的是（）。","opts":["A. 插入排序","B. 选择排序","C. 交换排序","D. 桶装排序"],"ans":3,"explain":"按所用排序策略的不同，内部排序方法又可以分为五类：插入、选择、交换、归并和分配排序。"},{"id":"ds02331-pl-P4092086","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在直接插入排序中，如果序列的初始状态为（4，2，6，5，1），那么排序过程中第一次插入操作后的序列是（）。","opts":["A. （1， 2， 6， 5， 4）","B. （1， 4， 2， 6， 5）","C. （2， 1， 6， 5， 4）","D. （2， 4， 1， 6， 5）"],"ans":1,"explain":"直接插入排序的工作原理是将序列分为已排序和未排序两部分。初始时，第一个元素4被视为已排序部分，其余元素为未排序部分。第一次插入操作是将第二个元素2与已排序部分的元素进行比较，并插入到合适的位置。由于4大于2，因此2应该插入到4之前，得到新的序列（1， 4， 2， 6， 5）。"},{"id":"ds02331-pl-P4092087","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"插入排序的特点是（）。","opts":["A. 频繁交换元素","B. 按关键字插入","C. 选择最小元素","D. 归并子序列"],"ans":1,"explain":"插入排序的基本思想是：每次将一个待排序的记录按其关键字的大小插入到前面已排好序的文件中的适当位置，直到全部记录插入完为止。"},{"id":"ds02331-pl-P4092088","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"若数据元素序列11，13，15，7，8，9，23，2，5是采用下列排序方法之一得到的第二趟排序后的结果，则该排序算法是（）。","opts":["A. 冒泡排序","B. 插入排序","C. 选择排序","D. 归并排序"],"ans":1,"explain":"插入排序（insertion Sort）的基本思想是：每次将一个待排序的记录，按其关键字大小插入到前面已经排好序的子文件中的适当位置，直到全部记录插入完成为止。"},{"id":"ds02331-pl-P4092089","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"对数据序列（25，15，7，18，10，0，4）采用直接插入排序进行升序排序，两趟排序后，得到的排序结果为（）。","opts":["A. 0，4，7，18，10，25，15","B. 0，4，25，15，7，18，10","C. 7，15，10，0，4，18，25","D. 7，15，25，18，10，0，4"],"ans":3,"explain":"初始【25】【15，7，18，10，0，4】第一趟【15，25】【7，18，10，0，4】第二趟【7，15，25】【18，10，0，4】"},{"id":"ds02331-pl-P4092090","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下列不稳定的排序方法是（）。","opts":["A. 希尔排序","B. 归并排序","C. 直接插入排序","D. 冒泡排序"],"ans":0,"explain":"内部排序方法的分析与比较中总结到，直接插入、冒泡、归并、基数排序算法是稳定的，直接选择、希尔、快速、堆排序算法是不稳定的。"},{"id":"ds02331-pl-P4092091","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"对数据序列（26，14，17，12，7，4，3）采用二路归并排序进行升序排序，两趟排序后，得到的排序结果为（）。","opts":["A. 14，26，17，12，4，7，3","B. 12，14，17，26，3，4，7","C. 14，26，12，17，3，4，7","D. 14，26，12，17，3，7，4"],"ans":1,"explain":"一趟结果为：【1416】【12 17】【47】3；二趟结果为：12，14，17，26，3，4，7。"},{"id":"ds02331-pl-P4092092","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下列排序算法中，在每一趟都能选出一个元素放到其最终位置上的是（）。","opts":["A. 插入排序","B. 希尔排序","C. 归并排序","D. 堆排序"],"ans":3,"explain":"堆排序的思想：在排序过程中，将记录数组看成一棵完全二叉树的顺序存储结构，利用完全二叉树中双亲结点和孩子结点之间的内在关系，在当前无序区中选择关键字最大或最小记录。"},{"id":"ds02331-pl-P4092093","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"一组记录的关键码为（45，68，57，13，24，89），利用堆排序算法进行升序排序，建立的初始堆为（）。","opts":["A. 68，45，57，13，24，89","B. 89，68，57，13，24，45","C. 89，68，57，45，24，13","D. 89，57，68，24，45，13"],"ans":1,"explain":"堆排序正是利用大根堆（或小根堆）来选取当前无序区中关键字最大（或最小）的记录实现排序的。每一趟排序的操作是：将当前无序区调整为一个大根堆，选取关键字最大的堆顶记录，将它和无序区中最后一个记录交换，这正好与选择排序相反。堆排序就是一个不断建堆的过程。"},{"id":"ds02331-pl-P4092094","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"一组记录的关键字为（35，48，47，23，44，88），利用堆排序算法进行降序排序，建立的初始堆为（）。","opts":["A. 23，35，48，47，44，88","B. 23，35，47，48，44，88","C. 35，23，47，48，44，88","D. 35，23，47，44，48，88"],"ans":1,"explain":"堆排序正是利用大根堆（或小根堆）来选取当前无序区中关键字最大（或最小）的记录实现排序的。每一趟排序的操作是：将当前无序区调整为一个大根堆，选取关键字最大的堆顶记录，将它和无序区中最后一个记录交换，这正好与选择排序相反。堆排序就是一个不断建堆的过程。"},{"id":"ds02331-pl-P4092095","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下列排序方法中，稳定的排序方法是（）。","opts":["A. 希尔排序","B. 归并排序","C. 堆排序","D. 快速排序"],"ans":1,"explain":"内部排序方法的分析与比较中总结到，直接插入、冒泡、归并、基数排序算法是稳定的，直接选择、希尔、快速、堆排序算法是不稳定的。"},{"id":"ds02331-pl-P4092096","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"希尔排序算法的时间复杂度较接近的答案的是（）。","opts":["A. O（nlog₂n）","B. O（n1.35）","C. O（n²）","D. O（d*（rd+n））"],"ans":0,"explain":"希尔排序算法的时间复杂度很难计算，有几种较接近的答案：O（nlog₂n）或O（n1.25）。"},{"id":"ds02331-pl-P4092097","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下列选项中，稳定的排序方法是（ ）。","opts":["A. 堆排序","B. 归并排序","C. 希尔排序","D. 快速排序"],"ans":1,"explain":"直接插入、冒泡、归并和基数排序算法是稳定的；直接选择、希尔、快速和堆排序算法是不稳定的。"},{"id":"ds02331-pl-P4092098","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"快速排序算法需要辅助空间为（）。","opts":["A. O（1）","B. O（n）","C. O（logzn）","D. O（n+rd）"],"ans":2,"explain":"快速排序算法需要辅助空间为O（logzn）。"},{"id":"ds02331-pl-P4092099","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"选取排序方法时需要考虑的主要因素不包括（）。","opts":["A. 待排序的记录个数","B. 记录本身的结果","C. 关键字的分布情况","D. 对排序稳定性的要求"],"ans":1,"explain":"选取排序方法时需要考虑的主要因素 （1）待排序的记录个数。 （2）记录本身的大小和存储结构。 （3）关键字的分布情况。 （4）对排序稳定性的要求。 （5）时间和空间复杂度等。"},{"id":"ds02331-pl-P4092100","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"当n很大，而且关键字位数较少时，排序方法的选取采用（）排序较好。","opts":["A. 直接插入","B. 快速","C. 归并","D. 链式基数"],"ans":3,"explain":"当n很大，而且关键字位数较少时，采用链式基数排序较好。"},{"id":"ds02331-pl-P4092101","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下列排序方法中，不宜在链表上实现的是（ ）。","opts":["A. 直接插入排序","B. 堆排序","C. 归并排序","D. 基数排序"],"ans":1,"explain":"一般的排序方法都可以在顺序结构（一维数组）上实现。当记录本身信息量较大时为了避免移动记录耗费大量的时间，可以采用链式存储结构。例如插入排序、归并排序、基数排序易于在链表上实现，使之减少记录的移动次数，但有的排序方法，如快速排序、堆排序在链表上却难于实现，在这种情况下，可以提取关键字建立索引表，然后对索引表进行排序。"},{"id":"ds02331-pl-P4092249","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：待排序记录的存储方式一般有三种：___、___和___形式。","opts":[],"ans":null,"explain":"顺序结构 链式结构 辅助表"},{"id":"ds02331-pl-P4092250","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定以下顺序栈的类型定义，请回答下列问题。 #define MaxSize 100 typedef struct { int data[MaxSize]； int top； } SeqStack； 规定栈底位置在数组下标为0的一端。 （1）用语句表示判断栈非空的条件。 （2）用语句表示连续k（k为正整数）次出栈的操作。","opts":[],"ans":null,"explain":"1）判断栈非空的条件是栈顶指针top不等于0。在C语言中，这可以用以下语句表示：<br/><br/>if （top != 0） {<br/>    // 栈非空<br/>}<br/>（2）连续k次出栈的操作需要在确保栈中至少有k个元素的前提下进行。这可以通过循环结构实现，每次循环都执行一次出栈操作，直到进行了k次或者栈为空为止。以下是C语言的实现语句：<br/><br/>int i；<br/>for （i = 0； i &lt; k &amp;&amp; top &gt;= 0； i++） {<br/>    // 假设有一个函数Pop（）用于出栈操作<br/>    Pop（&amp;seqStack）；<br/>}"},{"id":"ds02331-pl-P4092251","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定以下顺序队列的类型定义，请回答下列问题。 #define MaxSize 100 typedef struct { int data[MaxSize]； int front， rear； } SeqQueue； 规定队列的前端位置在数组下标为0的一端，后端位置在数组下标为rear的下一位置（rear加1是队列的下一个空闲位置）。 （1）用语句表示判断队列非空的条件。 （2）用语句表示连续k（k为正整数）次出队的操作。","opts":[],"ans":null,"explain":"（1）判断队列非空的条件是队列的前端front和后端rear指针不相等。在C语言中，这可以用以下语句表示：<br/><br/>if （front != rear） {<br/>    // 队列非空<br/>}<br/>（2）连续k次出队的操作需要在确保队列中至少有k个元素的前提下进行。以下是C语言的实现语句：<br/><br/>int i；<br/>for （i = 0； i &lt; k &amp;&amp; front != rear； i++） {<br/>    // 假设有一个函数Dequeue（）用于出队操作<br/>    Dequeue（&amp;seqQueue）；<br/>}"},{"id":"ds02331-pl-P4092252","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定以下链表的节点定义，请回答下列问题。 typedef struct ListNode { int value； struct ListNode *next； } ListNode； （1）编写一个函数，用于在链表的头部插入一个新节点。 （2）编写一个函数，用于删除链表中给定值的节点。","opts":[],"ans":null,"explain":"（1）在链表头部插入一个新节点的函数可以如下实现：<br/><br/>ListNode* insertAtHead（ListNode** head， int value） {<br/>    ListNode* newNode = （ListNode*）malloc（sizeof（ListNode））；<br/>    newNode-&gt;value = value；<br/>    newNode-&gt;next = *head；<br/>    *head = newNode；<br/>    return *head；<br/>}<br/>这个函数接受一个指向链表头节点的指针的地址和一个要插入的值。它创建一个新节点，将其next指针指向当前的头节点，然后将新节点设置为头节点。<br/><br/>（2）删除链表中给定值的节点的函数可以如下实现：<br/><br/>ListNode* deleteNode（ListNode* head， int value） {<br/>    if （head == NULL） return NULL；<br/>    if （head-&gt;value == value） {<br/>        ListNode* temp = head；<br/>        head = head-&gt;next；<br/>        free（temp）；<br/>        return head；<br/>    }<br/>    ListNode* current = head；<br/>    while （current-&gt;next != NULL） {<br/>        if （current-&gt;next-&gt;value == value） {<br/>            ListNode* temp = current-&gt;next；<br/>            current-&gt;next = current-&gt;next-&gt;next；<br/>            free（temp）；<br/>            return head；<br/>        }<br/>        current = current-&gt;next；<br/>    }<br/>    return head；<br/>}"},{"id":"ds02331-pl-P4092253","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：有以下数据序列（19，14，23，01，68，20，84，27，55，11，10，79，12），使用希尔排序方法将其排成升序序列。请回答下列问题。 （1）写出增量为4时对上述数据序列进行一趟希尔排序的结果。 （2）给出一个可行的希尔排序增量序列。","opts":[],"ans":null,"explain":"（1）12，11，10，01，19，14，23，27，55，20，84，79，68<br/>（2）4，2，1"},{"id":"ds02331-pl-P4092254","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：有数据序列（12，17，05，10，20，24，45，11，10，12），使用希尔排序方法将其排成升序序列。请分别写出增量为3和1的希尔排序结果。","opts":[],"ans":null,"explain":"（1）增量为3时希尔排序结果10 11 05 12 17 10 12 20 24 45；<br/>（2）增量为1时希尔排序结果：05 10 10 11 12 12 17 20 24 45。"},{"id":"ds02331-pl-P4092255","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：有数据序列（45，32，18，47，29，56，38，52，23，40），使用希尔排序方法将其排成升序序列。请回答下列问题。 （1）分别写出增量序列的取值依次为3，1的希尔排序结果。 （2）计算增量为3时希尔排序中数据元素之间的总交换次数（两个元素之间的交换记1次）。","opts":[],"ans":null,"explain":"（1）原始值：45，32，18，47，29，56，38，52，23，40<br/>增量为3：45，18，29，32，38，52，47，40，23，56<br/>增量为1：18，23，29，32，38，40，45，47，52，56<br/><br/>（2）在增量为3的希尔排序过程中，我们需要计算每趟排序中的交换次数，然后将它们相加得到总交换次数。以下是每趟排序的详细过程：<br/><br/>第1趟（增量为3）：<br/><br/>比较45和18，交换，得到18，45，29，32，38，52，47，40，23，56（交换1次）<br/>比较45和29，不交换<br/>比较32和38，交换，得到29，38，32，18，45，52，47，40，23，56（交换1次）<br/>比较52和47，交换，得到29，38，32，18，45，47，52，40，23，36（应为56，但这里可能是题目打印错误，下面按原题目计算）（交换1次）<br/>比较47和40，不交换<br/>比较23和36（应为56），交换，得到29，38，32，18，45，47，40，23，36（交换1次）<br/>总交换次数 = 1 + 1 + 1 + 1 = 4次"},{"id":"ds02331-pl-P4092256","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：在平均情况下，比较和移动记录的总次数大约为最坏情况下的一半，所以，冒泡排序算法的时间复杂度为___。","opts":[],"ans":null,"explain":"O（n²）"},{"id":"ds02331-pl-P4092257","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：对含n个元素的数据序列采用快速排序算法进行排序，平均时间复杂度是___。","opts":[],"ans":null,"explain":"O（nlogn）"},{"id":"ds02331-pl-P4092258","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：对含n个元素的数据序列采用快速排序算法进行排序，在最坏情况下的时间复杂度是___。","opts":[],"ans":null,"explain":"O（n²）"},{"id":"ds02331-pl-P4092259","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：一组记录的关键字为（45，53，18，49，36，76，13，97，36，32）利用快速排序方法对其进行排序，选择45为基准，一次划分后的结果为___。","opts":[],"ans":null,"explain":"32，36，18，13，36，45，76，97，49，53"},{"id":"ds02331-pl-P4092260","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定以下关键字序列（34，18，12，45，22，9，30），使用快速排序方法将其按升序排列。请回答下列问题。 （1）若取第一个关键字为基准，写出第一趟快速排序的结果。 （2）若取最后一个关键字为基准，写出第一趟快速排序的结果。","opts":[],"ans":null,"explain":"（1）若取第一个关键字（34）为基准，第一趟快速排序的结果如下：：18，12，9，22，30，34，45，22<br/>（2）若取最后一个关键字（30）为基准，第一趟快速排序的结果如下：：12，18，9，22，30，34，45，22"},{"id":"ds02331-pl-P4092261","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定以下数据序列（36，79，54，12，45，81，23，67，90，32，58，44），使用二路归并排序算法将其排成升序序列。给出前四趟排序结果。","opts":[],"ans":null,"explain":"初始：36，79，54，12，45，81，23，67，90，32，58，44<br/>一趟归并：<br/>12，36，45，54，23，32，36，44，58，67，79，81，90<br/>二趟归并：<br/>12，23，32，36，36，44，45，54，58，67，79，81，90<br/>三趟归并：<br/>12，23，32，36，36，44，45，54，58，67，79，81<br/>四趟归并：<br/>12，23，32，36，36，44，45，54，58，67，79"},{"id":"ds02331-pl-P4092262","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：箱排序又称___。","opts":[],"ans":null,"explain":"桶排序"},{"id":"ds02331-pl-P4092263","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：对箱排序的改进和推广的排序算法是___。","opts":[],"ans":null,"explain":"基数排序"},{"id":"ds02331-pl-P4092264","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：快速、归并、堆排序算法的时间复杂度为____。","opts":[],"ans":null,"explain":"O（nlog₂n）"},{"id":"ds02331-pl-P4092265","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：基数排序算法的时间复杂度为O（d*（rd+n）），其中___是基数，___是关键字的位数，___是元素个数。","opts":[],"ans":null,"explain":"rd d n"},{"id":"ds02331-pl-P4092266","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：基数排序算法需要辅助空间为___。","opts":[],"ans":null,"explain":"O（n+rd）"},{"id":"ds02331-pl-P4092267","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：若待排序的一组记录数目n较小（如n≤50）时，可采用___或___。","opts":[],"ans":null,"explain":"插入排序 选择排序"},{"id":"ds02331-pl-P4092268","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：关键字比较次数与记录的初始排列顺序无关的排序方法是___。","opts":[],"ans":null,"explain":"选择排序"},{"id":"ds02331-pl-P4092269","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：当记录本身信息量较大时，为了避免移动记录耗费大量的时间，可以采用___结构。","opts":[],"ans":null,"explain":"链式存储"},{"id":"ds02331-pl-P4092143","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：给定以下数据类型和顺序表定义，编写一个函数使用直接插入排序算法对顺序表按降序进行排序。 #define MAXSIZE 100 typedef int KeyType； typedef struct { KeyType key； // 其他记录字段 } RecType； typedef RecType SeqList[MAXSIZE]； void descendingInsertionSort（SeqList R， int n） { int i， j； RecType temp； for （i = 1； i &lt;= n - 1； i++） { temp = R[i]； （1）； while （j &gt;= 0 &amp;&amp; （2） ） { （3）； j--； } R[j + 1] = temp； } return； }","opts":[],"ans":null,"explain":"（1） j = i - 1<br/>（2） R[j].key &lt; temp.key<br/>（3） R[j + 1] = R[j]"},{"id":"ds02331-pl-P4092144","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：已知二叉树采用二叉链表存储，其结点结构定义如下： typedef struct Node { double data； struct Node *lchild， *rchild； } *BiTree； 请编写递归函数SumData（BiTree T），返回二叉树T中所有结点数据的总和。","opts":[],"ans":null,"explain":"double SumData（BiTree T） {<br/>    if （T == NULL） {<br/>        return 0；<br/>    } else {<br/>        return T-&gt;data + SumData（T-&gt;lchild） + SumData（T-&gt;rchild）；<br/>    }<br/>}<br/>这个函数会递归地计算左子树和右子树中所有结点数据的总和，并将当前结点的数据加入到总和中。"},{"id":"ds02331-pl-P4092145","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：给定一个待排序的整数数组，使用冒泡排序算法对其进行升序排序。请填写下列函数中的空白处，使算法完整。 void bubbleSort（int arr[]， int n） { int i， j； int temp； for （i = 0； i &lt; n - 1； i++） { for （j = 0； j &lt; （n - i - 1）； j++） { if （arr[j] &gt; arr[j + 1]） { （1） ； // 将较大的数往后移动 （2） ； arr[j + 1] = temp； // 完成交换 } } } return； }","opts":[],"ans":null,"explain":"（1）temp = arr[j]<br/>（2）arr[j] = arr[j + 1]"},{"id":"ds02331-pl-P4092146","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：实现一个双向选择排序算法，该算法类似于冒泡排序，但是每次从两端交替选择最小和最大的元素进行交换，直到整个序列有序。 请根据以下伪代码模板，填写缺失的部分以完成算法的实现： void DoubleSelectionSort（SeqList R， int n） { int i， j， minIndex， maxIndex； bool swap； #define MAXSIZE 100 typedef int KeyType； SeqList T[MAXSIZE]； for （i = 0； i &lt; n - 1； i++） { swap = true； （1）； （2）； for （j = i + 1； j &lt; n； j++） { if （R[j].key &lt; R[minIndex].key） { minIndex = j； } if （R[j].key &gt; R[maxIndex].key） { （3）； } } if （i != minIndex） { swap（R[i]， R[minIndex]）； } if （i != maxIndex） { swap（R[i]， R[maxIndex]）； } // 只在每次循环结束时检查是否需要继续排序 if （!swap） { break； // 如果没有发生交换，说明数组已经有序，退出循环 } } }","opts":[],"ans":null,"explain":"（1）minIndex = i   <br/>（2） maxIndex = i  <br/>（3）maxIndex = j"},{"id":"ds02331-pl-P4092147","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：编写一个双向插入排序算法，该算法在每一轮中同时从数组的两端开始，选择一个元素插入到已排序部分的适当位置，直到整个数组有序。 请根据以下伪代码模板，填写缺失的部分以完成算法的实现： void DoubleInsertionSort（SeqList R， int n） { int i， j， key； #define MAXSIZE 100 typedef int KeyType； SeqList T[MAXSIZE]； for （i = 1； i &lt; n； i++） { key = R[i].key； （1）； // 从后向前查找已排序部分，将大于key的元素后移一位 while （j &gt;= 0 &amp;&amp; R[j].key &gt; key） { （2）； j--； } // 插入key到正确的位置 R[j + 1].key = key； // 从前向后重复上述过程 j = i； while （j &gt; 0 &amp;&amp; R[j - 1].key &lt; key） { // 注意这里的条件是小于key R[j] = R[j - 1]； j--； } // 插入key到正确的位置 R[j].key = key； } }","opts":[],"ans":null,"explain":"（1） j = i - 1<br/>（2）R[j + 1] = R[j]"},{"id":"ds02331-pl-P4092148","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：设计一个双向归并排序算法，该算法将数组分成两部分，分别对这两部分进行排序，然后将两个已排序的部分合并成一个有序的数组。 请根据以下伪代码模板，填写缺失的部分以完成算法的实现： void DoubleMergeSort（SeqList R， int left， int right） { if （left &gt;= right） { return； } int mid = （left + right） / 2； DoubleMergeSort（R， left， mid）； DoubleMergeSort（R， mid + 1， right）； // 合并两个已排序的部分 Merge（R， left， mid， right）； } void Merge（SeqList R， int left， int mid， int right） { int i， j， k； int n1 = mid - left + 1； int n2 = right - mid； SeqList L[MAXSIZE]， R[MAXSIZE]； // 复制数据到临时数组 for （i = 0； i &lt; n1； i++） { L[i] = R[left + i]； } for （j = 0； j &lt; n2； j++） { R[j] = R[mid + 1 + j]； } i = 0； j = 0； k = left； // 合并临时数组回原数组 while （i &lt; n1 &amp;&amp; j &lt; n2） { if （L[i].key &lt;= R[j].key） { （1）； i++； } else { （2）； j++； } k++； } // 复制剩余的L数组元素 while （i &lt; n1） { R[k] = L[i]； i++； k++； } // 复制剩余的R数组元素 while （j &lt; n2） { R[k] = R[j]； j++； k++； } }","opts":[],"ans":null,"explain":"（1） R[k] = L[i]<br/>（2） R[k] = R[j]"},{"id":"ds02331-pl-P4092149","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：给定一个待排序的整数数组，使用选择排序算法对其进行升序排序。请填写下列函数中的空白处，使算法完整。 void selectionSort（int arr[]， int n） { int i， j， minIndex， temp； for （i = 0； i &lt; n - 1； i++） { （1） ； // 初始化最小值索引为当前位置 for （j = i + 1； j &lt; n； j++） { // 寻找[i， n-1]区间内的最小值索引 if （（2）） { minIndex = j； // 更新最小值索引 } } if （minIndex != i） { // 将找到的最小值与arr[i]交换位置 （3）； arr[i] = arr[minIndex]； arr[minIndex] = temp； } } return； }","opts":[],"ans":null,"explain":"（1） minIndex = i；<br/>（2） arr[j] &lt; arr[minIndex]<br/>（3） temp = arr[i]"},{"id":"ds02331-pl-P4092150","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法设计题：已知顺序表SeqList定义如下： typedef struct { KeyType key； InfoType otherinfo； } RecType； #define MAXSIZE 100 typedef RecType SeqList[MAXSIZE + 1]； 编写函数BidirectionalBubbleSort（SeqList R， int n），使用双向冒泡排序法将n个元素的待排序列R按关键字升序排序。第1趟将最小元素排在数组下标为0的位置，第2趟将最大元素排在数组下标为n-1的位置，依此类推，最后1趟将中间元素排在R的中心位置。","opts":[],"ans":null,"explain":"void BidirectionalBubbleSort（SeqList R， int n） {<br/>    int i， j， pass；<br/>    RecType temp；<br/>    int flag = 1； // 标志位，0表示不需要继续排序<br/>    for （pass = 1； pass &lt;= n / 2； pass++） {<br/>        flag = 1； // 重置标志位<br/>        for （i = 0； i &lt; n - pass； i++） {<br/>            if （R[i].key &gt; R[i + 1].key） {<br/>                // 交换两个元素的位置<br/>                temp = R[i]；<br/>                R[i] = R[i + 1]；<br/>                R[i + 1] = temp；<br/>                flag = 0； // 交换发生，需要继续排序<br/>            }<br/>        }<br/>        // 如果没有发生交换，说明已经排序完成<br/>        if （flag） break；<br/><br/>        // 反向冒泡，将最大元素移动到数组末尾<br/>        for （i = n - 1； i &gt; n - pass - 1； i--） {<br/>            if （R[i].key &lt; R[i - 1].key） {<br/>                temp = R[i]；<br/>                R[i] = R[i - 1]；<br/>                R[i - 1] = temp；<br/>                flag = 0； // 交换发生，需要继续排序<br/>            }<br/>        }<br/>    }<br/>}<br/>这个函数首先定义了一个标志位flag来确定是否需要继续排序。在每次冒泡过程中，如果没有发生任何交换，说明序列已经排序完成，可以提前结束排序。在每次正向冒泡后，函数会执行一次反向冒泡，确保每次循环都能将一个元素移动到正确的位置。正向冒泡用于将最小元素移动到序列的前端，而反向冒泡用于将最大元素移动到序列的末尾。通过这种方式，序列逐渐被排序。"},{"id":"ds02331-pl-P4092151","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：给定一个带头结点的单链表（头指针为head），编写一个函数reverseList，实现链表的逆序操作。请根据以下代码片段，回答相关问题。 void reverseList（LinkList head） { LinkNode *prev = NULL， *current = head-&gt;next， *next； while （current != NULL） { next = current-&gt;next； current-&gt;next = prev； prev = current； current = next； } head-&gt;next = prev； } （1）若线性表L=（6， 7， 8， 9， 10），保存在带头结点的单链表head中，依次列出执行reverseList（head）后链表中各元素的值。 （2）请指出该程序段的功能是什么。","opts":[],"ans":null,"explain":"（1）执行reverseList（head）后，链表L=（6， 7， 8， 9， 10）的逆序操作将得到新的链表顺序为（10， 9， 8， 7， 6）。具体来说，链表的头结点保持不变，原链表的第一个元素（值为6）成为最后一个元素，最后一个元素（值为10）成为第一个元素，其余元素的顺序依次向后移动。<br/><br/>（2）该程序段的功能是将一个带头结点的单链表进行逆序操作。它通过一个循环，每次取出链表中的一个节点，将其与前一个节点的链接断开，并将该节点的next指针指向前一个节点，从而逐步将链表的顺序颠倒。在循环结束后，头结点的next指针指向新的链表的第一个节点，即原链表的最后一个节点，完成链表的逆序。"},{"id":"ds02331-pl-P4092152","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：给定一个带头结点的单链表（头指针为head），编写一个函数deleteMiddle，实现删除链表中间节点的操作。请根据以下代码片段，回答相关问题。 void deleteMiddle（LinkList head） { LinkNode *p = head-&gt;next； if （p == NULL || p-&gt;next == NULL） { return； // 链表为空或只有一个节点，无法删除中间节点 } while （p-&gt;next-&gt;next != NULL） { p = p-&gt;next； } p-&gt;next = NULL； // 删除中间节点 } （1）若线性表M=（2， 4， 6， 8， 10），保存在带头结点的单链表head中，依次列出执行deleteMiddle（head）后链表中各元素的值。 （2）请指出该程序段的功能是什么。","opts":[],"ans":null,"explain":"（1）执行deleteMiddle（head）后，链表M=（2， 4， 6， 8， 10）的中间节点（值为8）将被删除，新的链表顺序为（2， 4， 6， 10）。<br/><br/>（2）该程序段的功能是删除一个带头结点的单链表的中间节点。它首先检查链表是否为空或只有一个节点，如果是，则无法进行删除操作。然后，通过一个循环找到链表的最后一个节点，将其next指针设置为NULL，从而删除链表的中间节点。注意，这个函数假设链表至少有两个节点。"},{"id":"ds02331-pl-P4092153","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：给定一个带头结点的单链表（头指针为head），编写一个函数sumList，计算链表中所有元素的和。请根据以下代码片段，回答相关问题。 int sumList（LinkList head） { LinkNode *p = head-&gt;next； int sum = 0； while （p != NULL） { sum += p-&gt;data； p = p-&gt;next； } return sum； } （1）若线性表N=（3， 5， 7， 2， 1），保存在带头结点的单链表head中，计算执行sumList（head）后得到的元素和。 （2）请指出该程序段的功能是什么。","opts":[],"ans":null,"explain":"（1）执行sumList（head）后，链表N=（3， 5， 7， 2， 1）中所有元素的和为18。<br/><br/>（2）该程序段的功能是计算一个带头结点的单链表中所有节点的数据之和。它通过一个循环遍历链表中的每个节点，累加每个节点的数据域data的值，最后返回总和。"},{"id":"ds02331-pl-P4092154","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：已知二叉树采用二叉链表存储，其结点结构定义如下： typedef struct Node { char data； struct Node *lchild， *rchild； } *BiTree； 请编写递归函数CountLeaves（BiTree T），返回二叉树T中叶子结点的总数。","opts":[],"ans":null,"explain":"int CountLeaves（BiTree T） {<br/>    if （T == NULL） {<br/>        return 0；<br/>    } else if （T-&gt;lchild == NULL &amp;&amp; T-&gt;rchild == NULL） {<br/>        return 1；<br/>    } else {<br/>        return CountLeaves（T-&gt;lchild） + CountLeaves（T-&gt;rchild）；<br/>    }<br/>}<br/>这个函数会检查当前结点是否是叶子结点（没有子结点），如果是，则返回1，否则递归地计算左子树和右子树中叶子结点的总数并相加。"},{"id":"ds02331-pl-P4092155","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法设计题：设计一个递归算法，计算一个整数数组中所有偶数之前的奇数个数。 例如，给定数组 arr = {1， 3， 2， 4， 5， 6}，算法应该返回 2，因为在第一个偶数 2 之前有两个奇数 1 和 3，在第二个偶数 4 之前有一个奇数 5。","opts":[],"ans":null,"explain":"以下是该算法的C语言实现：<br/><br/>int countOddsBeforeEvens（int arr[]， int index， int n） {<br/>    // 递归终止条件：如果索引超出数组长度，返回0<br/>    if （index &gt;= n） {<br/>        return 0；<br/>    }<br/>    <br/>    // 如果当前索引处的元素是偶数，返回0，因为没有奇数在它之前<br/>    if （arr[index] % 2 == 0） {<br/>        return 0；<br/>    }<br/>    <br/>    // 递归计算下一个索引处的奇数个数，并加1（包括当前索引处的奇数）<br/>    return 1 + countOddsBeforeEvens（arr， index + 1， n）；<br/>}<br/><br/>// 辅助函数，用于调用递归算法并返回结果<br/>int countOddsBeforeEvensInArray（int arr[]， int n） {<br/>    return countOddsBeforeEvens（arr， 0， n）；<br/>}<br/><br/>// 示例使用<br/>int main（） {<br/>    int arr[] = {1， 3， 2， 4， 5， 6}；<br/>    int n = sizeof（arr） / sizeof（arr[0]）；<br/>    int result = countOddsBeforeEvensInArray（arr， n）；<br/>    printf（&quot;The number of odds before evens is： %d\\n&quot;， result）；<br/>    return 0；<br/>}<br/>在这个算法中，我们定义了一个递归函数countOddsBeforeEvens，它接受一个整数数组arr、当前索引index和数组的长度n作为参数。函数从数组的开始遍历，每当遇到一个偶数时停止计数，并返回0。对于每个奇数，它递归地调用自己，并在返回值上加1。辅助函数countOddsBeforeEvensInArray用于初始化递归过程。在main函数中，我们创建了一个数组并调用了辅助函数来获取结果。"},{"id":"ds02331-pl-P4092156","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法设计题：设计一个递归算法，计算一个整数数组中所有奇数之后的偶数个数。 例如，给定数组 arr = {1， 3， 2， 4， 5， 6}，算法应该返回 3，因为在第一个奇数 1 之后有三个偶数 2， 4， 6，在第二个奇数 3 之后有两个偶数 4， 6。","opts":[],"ans":null,"explain":"以下是该算法的C语言实现：<br/><br/>int countEvensAfterOdds（int arr[]， int index， int n） {<br/>    // 递归终止条件：如果索引超出数组长度，返回0<br/>    if （index &gt;= n） {<br/>        return 0；<br/>    }<br/>    <br/>    // 如果当前索引处的元素是奇数，递归计算后面的偶数个数<br/>    if （arr[index] % 2 != 0） {<br/>        return 1 + countEvensAfterOdds（arr， index + 1， n）；<br/>    }<br/>    <br/>    // 如果当前索引处的元素是偶数，返回0，因为没有奇数在它之后<br/>    return 0；<br/>}<br/><br/>// 辅助函数，用于调用递归算法并返回结果<br/>int countEvensAfterOddsInArray（int arr[]， int n） {<br/>    return countEvensAfterOdds（arr， 0， n）；<br/>}<br/><br/>// 示例使用<br/>int main（） {<br/>    int arr[] = {1， 3， 2， 4， 5， 6}；<br/>    int n = sizeof（arr） / sizeof（arr[0]）；<br/>    int result = countEvensAfterOddsInArray（arr， n）；<br/>    printf（&quot;The number of evens after odds is： %d\\n&quot;， result）；<br/>    return 0；<br/>}<br/>在这个算法中，我们定义了一个递归函数countEvensAfterOdds，它接受一个整数数组arr、当前索引index和数组的长度n作为参数。函数从数组的开始遍历，每当遇到一个奇数时，递归地调用自己，并在返回值上加1，以计算后面的偶数个数。对于每个偶数，它直接返回0，因为没有奇数在它之后。辅助函数countEvensAfterOddsInArray用于初始化递归过程。在main函数中，我们创建了一个数组并调用了辅助函数来获取结果。"},{"id":"ds02331-pl-P4092639","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题： [图]https://file.mshiedu.com/exam/2024-3-22/xnCzu9ws98Ktn8tnqxYi8y3tyVpkAVfTG9eVQXOPaRd1v0evCP.png","opts":[],"ans":null,"explain":"输出结果：62，32，21，23，25，5，10，1，20，9。"},{"id":"ds02331-pl-P4092640","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：[图]https://file.mshiedu.com/exam/2024-3-22/wVZFFKnFvb3BtlXSO02jkUfM4qZytuEW8FJsEEoUT2cg9bWMG3.png","opts":[],"ans":null,"explain":"（1）n-1；（2）j--（或j=j-1）；（3）R[j]=temp"},{"id":"ds02331-pl-P4092641","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题： [图]https://file.mshiedu.com/exam/2024-3-22/nnSWHpoNEeN7rew0vqGNTg6MrNzMxs60NAzapFJjLTJ7xo1vyY.png","opts":[],"ans":null,"explain":"（1）j&gt;i；j--<br/>（2）j=i+1；j&lt;n-i-1<br/>（3）i++"},{"id":"ds02331-pl-P4092102","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"查找运算的主要操作是（）的比较。","opts":["A. 分析","B. 结果","C. 数据","D. 关键字"],"ans":3,"explain":"由于查找运算的主要操作是关键字的比较，因此，通常把查找过程中的平均比较次数（也称为平均查找长度）作为衡量一个查找算法效率优劣的标准。"},{"id":"ds02331-pl-P4092103","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"线性表采用顺序存储或链式存储，对其进行查找的方法应是（）。","opts":["A. 顺序查找","B. 二分查找","C. 散列查找","D. 索引查找"],"ans":0,"explain":"顺序查找无论是顺序存储或链式存储都同样适用，缺点就是效率低。 二分查找对象是顺序存储结构的有序表。"},{"id":"ds02331-pl-P4092104","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"设有序表为{1，3，9，12，32，41，45，62，75，77，82}，采用二分查找法查找关键字75，查找过程中关键字之间的比较次数是（）。","opts":["A. 1","B. 2","C. 3","D. 4"],"ans":1,"explain":"第一次比较时mid=6，第二次mid=9，正好是关键字75。"},{"id":"ds02331-pl-P4092105","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"由于二分查找是在有序表上进行的，所以其对应的判定树必定是一棵（）。","opts":["A. 二叉查找树","B. 二叉搜索树","C. 二叉分布树","D. 二叉排序树"],"ans":3,"explain":"由于二分查找是在有序表上进行的，所以其对应的判定树必定是一棵二叉排序树。"},{"id":"ds02331-pl-P4092106","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"二分查找算法在查找成功时，进行关键字比较的次数最多不超过（）。","opts":["A. 数组的长度","B. 判定树的深度","C. 关键的字数","D. 树的高度"],"ans":1,"explain":"二分查找算法在查找成功时，进行关键字比较的次数最多不超过判定树的深度。"},{"id":"ds02331-pl-P4092107","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"索引顺序查找又称（）。","opts":["A. 二分查找","B. 直接插入","C. 分块查找","D. 哈希查找"],"ans":2,"explain":"索引顺序查找又称分块查找，是一种介于顺序查找和二分查找之间的查找方法。"},{"id":"ds02331-pl-P4092108","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"二分查找的速度快，效率高，查找成功的平均查找长度约为（）。","opts":["A. log₂（n）","B. log₂（n+1）","C. log₂（n+1）-1","D. log₂（n-1）"],"ans":2,"explain":"二分查找的速度快，效率高，查找成功的平均查找长度约为1og₂（n+1）-1，但是它要求表以顺序存储表示并且是按关键字有序，使用高效率的排序方法也要花费O（nlog₂n）的时间。"},{"id":"ds02331-pl-P4092109","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"一棵二叉排序树中，关键字n所在结点是关键字m所在结点的祖先，则（）。","opts":["A. n一定大于m","B. n一定小于m","C. n一定等于m","D. n与m的大小关系不确定"],"ans":3,"explain":"由二叉排序树定义可知，其右子树上所有结点的值均大于根结点的值，则左子树上所有结点的值均小于根结点的值，因为题目中m和n并没有给出是左子树还是右子树，所以大小关系不确定。"},{"id":"ds02331-pl-P4092110","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"二叉排序树若右子树非空，则右子树上所有结点的值均（）根结点的值。","opts":["A. 大于","B. 小于","C. 等于","D. 不确定"],"ans":0,"explain":"二叉排序树，若它的右子树非空，则右子树上所有结点的值均大于根结点的值。"},{"id":"ds02331-pl-P4092111","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"若根结点不是叶子，则它至少有（）棵子树。","opts":["A. 2","B. 3","C. 4","D. 5"],"ans":0,"explain":"若树为非空，则根结点至少有1个关键字，至多有m-1个关键字。因此，若根结点不是叶子，则它至少有两棵子树。"},{"id":"ds02331-pl-P4092112","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"下面关于m阶（m≥3）B树的叙述中，正确的是（ ）。","opts":["A. 终端结点可位于不同层","B. 非终端结点至多有m棵子树","C. 若树非空，则根结点至少有2个关键字","D. 每个非根结点包含n个关键字，[m/2]≤n≤m"],"ans":1,"explain":"B树的所有的叶结点都在同一层上，A选项错误。每个非根结点包含n个关键字，[m/2]-1≤n≤m-1。D错误。"},{"id":"ds02331-pl-P4092113","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"B+树是一种常用于（）的B树的变形树。","opts":["A. 终端结点","B. 文件组织","C. 系统组织","D. 数据分析"],"ans":1,"explain":"B+树是一种常用于文件组织的B树的变形树。"},{"id":"ds02331-pl-P4092114","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"散列存储中使用的函数H（key）称为散列函数或哈希函数，它实现关键字到（）的映射（或称转换）。","opts":["A. 终端结点","B. 存储地址","C. 系统组织","D. 数据分析"],"ans":1,"explain":"散列存储中使用的函数H（key）称为散列函数或哈希函数，它实现关键字到存储地址的映射（或称转换）。"},{"id":"ds02331-pl-P4092115","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"平方取中法是取关键字（）作为散列地址的方法。","opts":["A. 平方","B. 平方的几位","C. 平方的后方几位","D. 平方的中间几位"],"ans":3,"explain":"平方取中法是取关键字平方的中间几位作为散列地址的方法，因为一个乘积的中间几位和乘数的每一位都相关，故由此产生的散列地址较为均匀，具体取多少位视实际情况而定。"},{"id":"ds02331-pl-P4092116","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"移位叠加是将各段的（）位对齐，然后相加。","opts":["A. 最低","B. 最高","C. 居中","D. 顶端"],"ans":0,"explain":"移位叠加是将各段的最低位对齐，然后相加；边界叠加则是将两个相邻的段沿边界来回折叠，然后对齐相加。"},{"id":"ds02331-pl-P4092117","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"线性探查法的基本思想是：将散列表T[0.m-1]看成一个（）。","opts":["A. 单向向量","B. 双向向量","C. 双边向量","D. 循环向量"],"ans":3,"explain":"线性探查法的基本思想是：将散列表T[0.m-1]看成一个循环向量，若初始探查的地址为d（即H（key）=d），则后续探查地址的序列为：d+1，d+2，…，m-1，0，1，…，d-1。"},{"id":"ds02331-pl-P4092118","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"设散列表长m=14，散列函数H（key）=key%11。表中已保存4个关键字：addr（15）=4，addr（38）=5，addr（61）=6，addr（84）=7，其余地址均为空。保存关键字49时存在冲突，采用线性探查法来处理。则查找关键字49时的探查次数是（）。","opts":["A. 1","B. 2","C. 4","D. 8"],"ans":2,"explain":"h（49）=5，散列地址5已经被占，因此探查h1=（5+1）%11=6，但散列地址6也已经被占，再探查h2=（6+1）%11=7，散列地址7也被占了，再探查h3=（7+1）%11=8，此地址是开放的，可将49插入。"},{"id":"ds02331-pl-P4092119","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"考虑广义表LR=（27，（3，（4，5），6），7），LR的表尾是（ ）。","opts":["A. （（3，（4，5）），6），7","B. （（3，（4，5）），7）","C. （27，（3，（4，5）），6）","D. （27，（3，（4，5）），6，7）"],"ans":1,"explain":"在广义表LR中，表头是27，而表尾是（3，（4，5），6），7。由于表尾本身也是一个广义表，我们可以继续提取表尾，直到没有子表为止。因此，最终的表尾是（（3，（4，5）），7）。"},{"id":"ds02331-pl-P4092120","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"设散列表长m=16，散列函数H（key）=key%15。表中已保存4个关键字addr（18）=3，addr（35）=5，addr（51）=6，addr（22）=7，其余地址均为开放地址。存储关键字36时存在冲突，采用线性探测法来处理。则查找关键字36时的探查次数是（）。","opts":["A. 1","B. 2","C. 3","D. 4"],"ans":2,"explain":"散列地6已经被占，因此探查h1=（6+1）%15=7，但散【解析】h（36）=6，列地址7也已经被占，再探查h2=（7+1）%15=8，此地址是开放的，可将49插入，所以探测了3次。"},{"id":"ds02331-pl-P4092121","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在设计散列表时可通过选择（）来控制散列表的平均查找长度。","opts":["A. 填充率α","B. 负载因子α","C. 填充系数α","D. 装填因子α"],"ans":3,"explain":"散列表的平均查找长度不是结点个数n的函数，而是装填因子α的函数，因此在设计散列表时可通过选择装填因子α来控制散列表的平均查找长度。"},{"id":"ds02331-pl-P4092627","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"对下图进行深度优先遍历，下列选项中，正确的遍历序列是（）。 [图]https://file.mshiedu.com/exam/2024-3-22/F06U2xC6gI0Xmg76UsRUYS5HhBwgUBUoiqg1ifIboApCD7kZ7A.png","opts":["A. v0，v1，v2，v5，v4，V₆，V₃，V6，V8","B. v0，v1，v2，v8，v4，V₆，V₃，V6，V5","C. v8，v1，v2，v5，v4，V₆，V₃，V6，V0","D. v0，v6，v2，v5，v4，V₆，V₃，V1，V8"],"ans":0,"explain":"深度优先搜索遍历图G8的顶点访问序列：v0，v1，v2，v5，v4，V₆，V₃，V6，V8。"},{"id":"ds02331-pl-P4092628","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"如图所示是一棵二叉排序树，树中每个结点的关键字都大于它左子树中所有结点的关键字，而小于它右子树中所有结点的关键字。若对下图其进行中序遍历，得到的遍历序列为（）。 [图]https://file.mshiedu.com/exam/2024-3-22/aLl8WtBXMLF73EhUH5oVEnhQgSmyAtEQkLjhHXQGrQd0ULO2l2.png","opts":["A. 13，15，18，26，34，43，49，56","B. 56，15，18，26，34，43，49，13","C. 56，49，43，34，26，18，15，13","D. 13，15，26，18，34，43，49，56"],"ans":0,"explain":"若对其进行中序遍历，得到的遍历序列为：13，15，18，26，34，43，49，56。可见，此序列是一个有序序列。"},{"id":"ds02331-pl-P4092270","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：通常把查找过程中的___作为衡量一个查找算法效率优劣的标准。","opts":[],"ans":null,"explain":"平均比较次数"},{"id":"ds02331-pl-P4092271","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：顺序查找（Sequential Search）又称___，是一种最简单和最基本的查找方法。","opts":[],"ans":null,"explain":"线性查找"},{"id":"ds02331-pl-P4092272","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：假设顺序存储的有序表R含有8个关键字，进行二分查找时，平均查找长度为__。","opts":[],"ans":null,"explain":"21/8（或2.625）"},{"id":"ds02331-pl-P4092273","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：假设顺序存储的有序表R含有12个关键字，进行二分查找时，平均查找 长度为___。","opts":[],"ans":null,"explain":"37/12，约为3.08"},{"id":"ds02331-pl-P4092274","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：索引顺序查找又称分块查找，是一种介于___和___之间的查找方法。","opts":[],"ans":null,"explain":"顺序查找 二分查找"},{"id":"ds02331-pl-P4092275","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：设定关键字序列为：37， 49， 26， 74， 85， 12， 53， 28。已知散列表地址空间为0~7，散列函数为H（k） = k mod 8，采用二次探查再散列法解决冲突。请完成以下任务： （1）将所给关键字数据依次填入该散列表中。 （2）计算等概率下查找成功的平均查找长度（ASL，Average Search Length）。","opts":[],"ans":null,"explain":"（1）根据给定的散列函数 H（k） = k mod 8，我们将每个关键字映射到散列表的地址，并使用二次探查再散列法解决冲突。<br/>最终散列表如下：<br/><br/>地址  0    1    2    3    4    5    6    7<br/>关键字 85   12   26   37   53   74   -    49<br/>（2）计算等概率下查找成功的平均查找长度（ASL）：<br/><br/>ASL = （1+1+1+1+1+1+1+4+4） / 9 = （14+8） / 9 = 22 / 9 ≈ 2.44<br/><br/>在等概率的情况下，查找成功的平均查找长度是所有关键字的查找长度之和除以关键字的数量。对于没有冲突的关键字，查找长度为1；对于有冲突的关键字，查找长度是找到空闲位置所需的探测次数。在这个例子中，85和12各需要4次探测，其余关键字均无需探测。因此，ASL大约为2.44。"},{"id":"ds02331-pl-P4092276","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：散列存储中，常用的解决冲突的方法有开放地址法和___。","opts":[],"ans":null,"explain":"拉链法（或链地址法）"},{"id":"ds02331-pl-P4092277","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：设有一个哈希表，其长度为8，使用除留余数法作为哈希函数。给定关键字序列 18， 23， 10， 29， 5， 14， 36，请将它们依次通过哈希函数映射到哈希表中，并指出每个关键字在哈希表中的数组下标位置。假设哈希表的数组下标从0开始。","opts":[],"ans":null,"explain":"下标：   0  1  2  3  4  5  6  7<br/>值：      -  29 18 14  -  5  36 23"},{"id":"ds02331-pl-P4092278","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：设有一个长度为9的哈希表，使用平方哈希法作为哈希函数。给定关键字序列 21， 34， 46， 23， 15， 4， 39， 58，请将它们依次通过哈希函数映射到哈希表中，并指出每个关键字在哈希表中的数组下标位置。假设哈希表的数组下标从0开始，且哈希表初始化为空。","opts":[],"ans":null,"explain":"下标：   0  1  2  3  4  5  6  7  8<br/>值：      15 39  34  21 4    23 58  -  -"},{"id":"ds02331-pl-P4092279","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：折叠法又分___和___。","opts":[],"ans":null,"explain":"移位叠加 边界叠加"},{"id":"ds02331-pl-P4092280","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定一个整数序列 （45， 28， 54， 15， 42， 36），使用二路归并排序算法进行升序排序。请给出最终排序后的序列。","opts":[],"ans":null,"explain":"最终排序后的序列为：（15， 28， 36， 42， 45， 54）。"},{"id":"ds02331-pl-P4092281","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定一个浮点数序列 （3.14， 2.71， 1.41， 5.55， 7.32， 9.86），使用归并排序算法进行降序排序。请给出最终排序后的序列。","opts":[],"ans":null,"explain":"最终排序后的序列为：（9.86， 7.32， 5.55， 3.14， 2.71， 1.41）。"},{"id":"ds02331-pl-P4092282","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定一个字符串序列 （&quot;apple&quot;， &quot;banana&quot;， &quot;cherry&quot;， &quot;date&quot;， &quot;fig&quot;， &quot;grape&quot;），使用归并排序算法按字典序进行升序排序。请给出最终排序后的序列。","opts":[],"ans":null,"explain":"最终排序后的序列为：（&quot;apple&quot;， &quot;banana&quot;， &quot;cherry&quot;， &quot;date&quot;， &quot;fig&quot;， &quot;grape&quot;）。"},{"id":"ds02331-pl-P4092283","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题：散列表的平均查找长度不是结点个数n的函数，而是___的函数。","opts":[],"ans":null,"explain":"装填因子α"},{"id":"ds02331-pl-P4092284","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定两个栈共享一个数组空间 data[n]（定义如下），它们的栈底分别设在数组的两端（初始化后 top1 = 0， top2 = n - 1）。 typedef struct { int data[n]； int top1； int top2； } DualStack； 现在有两个栈 stack1 和 stack2 共享同一个数组 data，并且它们的栈底分别设在数组的两端。编写以下两个函数： （1）编写判断栈满的函数 int isFull（DualStack *s），该函数应该返回一个整型值，如果栈已满，则返回 1，否则返回 0。 （2）编写压栈函数 void push（DualStack *s， int si， int x），其中 si 取值为 0 或 1，分别表示栈底为 0 或 n - 1 的栈。如果压栈操作成功，则更新栈顶位置并返回；如果栈已满，则不进行操作。","opts":[],"ans":null,"explain":"（1）判断栈满的函数 isFull 的实现：<br/><br/>int isFull（DualStack *s） {<br/>    // 如果栈1的栈顶和栈2的栈顶相邻，则栈已满<br/>    return （s-&gt;top1 == s-&gt;top2 - 1）；<br/>}<br/>（2）压栈函数 push 的实现：<br/><br/>void push（DualStack *s， int si， int x） {<br/>    if （isFull（s）） {<br/>        // 栈已满，不进行操作<br/>        return；<br/>    }<br/><br/>    if （si == 0） {<br/>        // 栈底为0的栈<br/>        s-&gt;data[s-&gt;top1++] = x；<br/>    } else {<br/>        // 栈底为n-1的栈<br/>        s-&gt;data[s-&gt;top2--] = x；<br/>    }<br/>}"},{"id":"ds02331-pl-P4092285","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定一个共享数组空间的两个队列 queue1 和 queue2，它们的队尾分别设在数组的两端（初始化后 rear1 = 0， front2 = n - 1）。编写以下两个函数： （1）编写判断队列满的函数 int isQueueFull（Queue *q），该函数应该返回一个布尔值，如果队列已满，则返回 true，否则返回 false。 （2）编写入队函数 void enqueue（Queue *q， int x），如果入队操作成功，则更新队尾位置并返回；如果队列已满，则不进行操作。 假设队列结构体定义如下： typedef struct { int data[n]； int front1； int rear1； int front2； int rear2； } Queue；","opts":[],"ans":null,"explain":"（1）判断队列满的函数 isQueueFull 的实现：<br/><br/>int isQueueFull（Queue *q） {<br/>    // 如果队列1的队尾和队列2的队头相邻，则队列已满<br/>    return （q-&gt;rear1 + 1 == q-&gt;front2）；<br/>}<br/>（2）入队函数 enqueue 的实现：<br/><br/>void enqueue（Queue *q， int x） {<br/>    if （isQueueFull（q）） {<br/>        // 队列已满，不进行操作<br/>        return；<br/>    }<br/><br/>    // 入队操作<br/>    q-&gt;data[q-&gt;rear1] = x；<br/>    q-&gt;rear1 = （q-&gt;rear1 + 1） % n；<br/>}"},{"id":"ds02331-pl-P4092286","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：给定一个共享数组空间的两个循环双向链表 list1 和 list2，它们的头节点分别设在数组的两端（初始化后 head1 = 0， head2 = n - 1）。编写以下函数： 编写判断链表满的函数 int isListFull（List *l），该函数应该返回一个布尔值，如果链表已满，则返回 true，否则返回 false。 假设链表结构体定义如下： typedef struct Node { int value； struct Node *prev； struct Node *next； } Node； typedef struct { Node data[n]； int head1； int head2； } List；","opts":[],"ans":null,"explain":"判断链表满的函数 isListFull 的实现：<br/><br/>int isListFull（List *l） {<br/>    // 如果链表1的尾节点的下一个节点是链表2的头节点，则链表已满<br/>    return （l-&gt;data[l-&gt;head1].next == l-&gt;head2）；<br/>}"},{"id":"ds02331-pl-P4092651","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：设关键字序列为：53，15，72，52，48，67，63，23。已知散列表地址空间为0~11，散列函数为H（k）=kmod11，采用线性探查再散列法解决冲突。 （1）将所给关键字数据依次填入该散列表中； （2）计算等概率下查找成功的平均查找长度。","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/IA6iIWcRoKu9NcFNNxYFCQHbFUtTb3iEMEmtdmNvtJtJ4I8yWc.png\"/>"},{"id":"ds02331-pl-P4092652","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题：[图]https://file.mshiedu.com/exam/2024-3-22/8qMK54OC4DlNldSRQsAURnhDm92ttdthAlskOApZmM1L0ugscR.png","opts":[],"ans":null,"explain":"（1）agebfdc<br/>（2）4个"},{"id":"ds02331-pl-P4092653","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"解答题： [图]https://file.mshiedu.com/exam/2024-3-22/MMyrH8Vc7NxU2KVOzkZUr51xKdcpY5YqQKB0nrdZ4MOaYVj4d3.png","opts":[],"ans":null,"explain":"<img src=\"https://file.mshiedu.com/exam/2024-3-22/kELg2Jvkb0bw4Iv71qlIdKt3Bts6ZVC610s6dbHei3zHy7XB86.png\"/>"},{"id":"ds02331-pl-P4092157","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法设计题：已知二叉树采用二叉链表存储，其结点结构定义如下： typedef int ElmType； typedef struct Node { ElmType data； struct Node *lchild， *rchild； } *BiTree； 请编写递归函数MaxDepth（BiTree T），返回二叉树T的最大深度。","opts":[],"ans":null,"explain":"int MaxDepth（BiTree T） {<br/>    if （T == NULL） {<br/>        return 0；<br/>    } else {<br/>        int leftDepth = MaxDepth（T-&gt;lchild）；<br/>        int rightDepth = MaxDepth（T-&gt;rchild）；<br/>        return （leftDepth &gt; rightDepth ? leftDepth ： rightDepth） + 1；<br/>    }<br/>}<br/>这个函数会递归地计算左子树和右子树的最大深度，然后取两者中的较大值加1（当前节点的深度）作为结果。"},{"id":"ds02331-pl-P4092642","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"算法阅读题：[图]https://file.mshiedu.com/exam/2024-3-22/7pDFODMHTdRHBtnyL0h5iqU3zIfT5RQBDLN0fJR8LMFSxHtDxj.png","opts":[],"ans":null,"explain":"（1）15 16 18 20 30 40<br/>（2）查找二叉排序树T中所有满足k1≦key≦k2，的元素，并按升序输出"}];
